/* DAWAH X — ahmad, অধ্যায় 3 · খণ্ড 3 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][3]=[[401,401,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عَلِيًّا ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فِي يَوْمِ الْفِطْرِ وَالنَّحْرِ يُصَلِّيَانِ ثُمَّ يَنْصَرِفَانِ فَيُذَكِّرَانِ النَّاسَ فَسَمِعْتُهُمَا يَقُولَانِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ هَذَيْنِ الْيَوْمَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ الْجُنْدَعِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ رَأَيْتُ أَمِيرَ الْمُؤْمِنِينَ ‏ ‏عُثْمَانَ ‏ ‏يَتَوَضَّأُ ‏ ‏فَأَهْرَاقَ ‏ ‏عَلَى يَدَيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ اسْتَنْثَرَ ثَلَاثَ مَرَّاتٍ وَمَضْمَضَ ثَلَاثًا وَذَكَرَ الْحَدِيثَ مِثْلَ مَعْنَى حَدِيثِ ‏ ‏مَعْمَرٍ ‏","","",""],[402,402,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ قَبِيصَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ أَلَا ‏ ‏أُرِيكُمْ ‏ ‏كَيْفَ كَانَ وُضُوءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى ‏ ‏فَدَعَا بِمَاءٍ فَتَمَضْمَضَ ثَلَاثًا ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَغَسَلَ قَدَمَيْهِ ثَلَاثًا ثُمَّ قَالَ وَاعْلَمُوا أَنَّ الْأُذُنَيْنِ مِنْ الرَّأْسِ ثُمَّ قَالَ قَدْ تَحَرَّيْتُ لَكُمْ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[403,403,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ الْأَعْرَابِيُّ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ الْجُهَنِىِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَدَعَا بِمَاءٍ فَتَوَضَّأَ فَلَمَّا فَرَغَ مِنْ وُضُوئِهِ تَبَسَّمَ فَقَالَ هَلْ تَدْرُونَ مِمَّا ضَحِكْتُ قَالَ فَقَالَ تَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا تَوَضَّأْتُ ثُمَّ تَبَسَّمَ ثُمَّ قَالَ هَلْ تَدْرُونَ مِمَّ ضَحِكْتُ قَالَ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏إِنَّ الْعَبْدَ إِذَا تَوَضَّأَ فَأَتَمَّ وُضُوءَهُ ثُمَّ دَخَلَ فِي صَلَاتِهِ فَأَتَمَّ صَلَاتَهُ خَرَجَ مِنْ صَلَاتِهِ كَمَا خَرَجَ مِنْ بَطْنِ أُمِّهِ مِنْ الذُّنُوبِ ‏","","",""],[404,404,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَنْهَى عَنْ الْمُتْعَةِ ‏ ‏وَعَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُفْتِي بِهَا فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَوْلًا فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَقَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ذَلِكَ قَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَجَلْ وَلَكِنَّا كُنَّا خَائِفِينَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏مَا كَانَ خَوْفُهُمْ قَالَ لَا أَدْرِي ‏","","",""],[405,405,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَنْهَى عَنْ الْمُتْعَةِ ‏ ‏وَعَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَأْمُرُ بِهَا فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لِعَلِيٍّ ‏ ‏قَوْلًا ثُمَّ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَقَدْ عَلِمْتَ أَنَّا قَدْ ‏ ‏تَمَتَّعْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَجَلْ وَلَكِنَّا كُنَّا خَائِفِينَ ‏","","",""],[406,406,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَخْطُبُ عَلَى مِنْبَرِهِ إِنِّي مُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَانَ يَمْنَعُنِي أَنْ أُحَدِّثَكُمْ إِلَّا الضِّنُّ عَلَيْكُمْ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏حَرَسُ لَيْلَةٍ فِي سَبِيلِ اللَّهِ تَعَالَى أَفْضَلُ مِنْ أَلْفِ لَيْلَةٍ يُقَامُ لَيْلُهَا وَيُصَامُ نَهَارُهَا ‏","","",""],[407,407,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْكَبِيرِ بْنُ عَبْدِ الْمَجِيدِ أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَنَى مَسْجِدًا لِلَّهِ عَزَّ وَجَلَّ بَنَى اللَّهُ لَهُ مِثْلَهُ فِي الْجَنَّةِ ‏","","",""],[408,408,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالِدِ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَعُثْمَانَ ‏ ‏يُصَلِّيَانِ يَوْمَ الْفِطْرِ وَالْأَضْحَى ثُمَّ يَنْصَرِفَانِ يُذَكِّرَانِ النَّاسَ قَالَ وَسَمِعْتُهُمَا يَقُولَانِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صِيَامِ هَذَيْنِ الْيَوْمَيْنِ ‏","","",""],[409,409,"","","‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبْقَى مِنْ نُسُكِكُمْ عِنْدَكُمْ شَيْءٌ بَعْدَ ثَلَاثٍ ‏","","",""],[410,410,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏ابْنِ دَارَةَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏قَالَ فَسَمِعَنِي أُمَضْمِضُ قَالَ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏قَالَ قُلْتُ لَبَّيْكَ قَالَ أَلَا أُخْبِرُكَ عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ بِالْمَقَاعِدِ ‏ ‏دَعَا بِوَضُوءٍ فَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ ثَلَاثًا وَغَسَلَ قَدَمَيْهِ ثُمَّ قَالَ مَنْ أَحَبَّ أَنْ يَنْظُرَ إِلَى وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَذَا وُضُوءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[411,411,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ مَحْصُورٌ فِي الدَّارِ فَدَخَلَ مَدْخَلًا كَانَ إِذَا دَخَلَهُ يَسْمَعُ كَلَامَهُ مَنْ عَلَى الْبَلَاطِ قَالَ فَدَخَلَ ذَلِكَ الْمَدْخَلَ وَخَرَجَ إِلَيْنَا فَقَالَ إِنَّهُمْ يَتَوَعَّدُونِي بِالْقَتْلِ ‏ ‏آنِفًا ‏ ‏قَالَ قُلْنَا ‏ ‏يَكْفِيكَهُمُ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ وَبِمَ يَقْتُلُونَنِي إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ رَجُلٌ كَفَرَ بَعْدَ إِسْلَامِهِ أَوْ زَنَى بَعْدَ إِحْصَانِهِ أَوْ قَتَلَ نَفْسًا فَيُقْتَلُ بِهَا ‏ ‏فَوَاللَّهِ مَا أَحْبَبْتُ أَنَّ لِي بِدِينِي بَدَلًا مُنْذُ هَدَانِي اللَّهُ وَلَا زَنَيْتُ فِي ‏ ‏جَاهِلِيَّةٍ وَلَا فِي إِسْلَامٍ قَطُّ وَلَا قَتَلْتُ نَفْسًا فَبِمَ يَقْتُلُونَنِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏إِنِّي لَمَعَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي الدَّارِ وَهُوَ مَحْصُورٌ وَقَالَ كُنَّا نَدْخُلُ مَدْخَلًا فَذَكَرَ الْحَدِيثَ مِثْلَهُ وَقَالَ قَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فَذَكَرَ الْحَدِيثَ مِثْلَهُ ‏ ‏أَوْ نَحْوَهُ ‏","","",""],[412,412,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ يَعْنِي ابْنَ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏دَعَا ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏نَاسًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏فَقَالَ إِنِّي سَائِلُكُمْ وَإِنِّي أُحِبُّ أَنْ تَصْدُقُونِي نَشَدْتُكُمْ اللَّهَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُؤْثِرُ ‏ ‏قُرَيْشًا ‏ ‏عَلَى سَائِرِ النَّاسِ وَيُؤْثِرُ ‏ ‏بَنِي هَاشِمٍ ‏ ‏عَلَى سَائِرِ ‏ ‏قُرَيْشٍ ‏ ‏فَسَكَتَ الْقَوْمُ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَوْ أَنَّ بِيَدِي مَفَاتِيحَ الْجَنَّةِ لَأَعْطَيْتُهَا ‏ ‏بَنِي أُمَيَّةَ ‏ ‏حَتَّى يَدْخُلُوا مِنْ عِنْدِ آخِرِهِمْ ‏ ‏فَبَعَثَ إِلَى ‏ ‏طَلْحَةَ ‏ ‏وَالزُّبَيْرِ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَا أُحَدِّثُكُمَا عَنْهُ ‏ ‏يَعْنِي ‏ ‏عَمَّارًا ‏ ‏أَقْبَلْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آخِذًا بِيَدِي ‏ ‏نَتَمَشَّى فِي ‏ ‏الْبَطْحَاءِ ‏ ‏حَتَّى أَتَى عَلَى أَبِيهِ وَأُمِّهِ وَعَلَيْهِ يُعَذَّبُونَ فَقَالَ ‏ ‏أَبُو عَمَّارٍ ‏ ‏يَا رَسُولَ اللَّهِ الدَّهْرَ هَكَذَا فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اصْبِرْ ثُمَّ قَالَ اللَّهُمَّ اغْفِرْ لِآلِ ‏ ‏يَاسِرٍ ‏ ‏وَقَدْ فَعَلْتُ ‏","","",""],[413,413,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حُرَيْثُ بْنُ السَّائِبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏حُمْرَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ شَيْءٍ سِوَى ظِلِّ بَيْتٍ ‏ ‏وَجِلْفِ الْخُبْزِ ‏ ‏وَثَوْبٍ ‏ ‏يُوَارِي ‏ ‏عَوْرَتَهُ وَالْمَاءِ فَمَا فَضَلَ عَنْ هَذَا فَلَيْسَ لِابْنِ ‏ ‏آدَمَ ‏ ‏فِيهِ حَقٌّ ‏","","",""],[414,414,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏ثَقِيفٍ ‏ ‏ذَكَرَهُ ‏ ‏حُمَيْدٌ ‏ ‏بِصَلَاحٍ ‏ ‏ذَكَرَ أَنَّ ‏ ‏عَمَّهُ ‏ ‏أخْبَرَهُ أَنَّهُ ‏ ‏رَأَى ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏جَلَسَ عَلَى الْبَابِ الثَّانِي مِنْ ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا بِكَتِفٍ فَتَعَرَّقَهَا ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ثُمَّ قَالَ جَلَسْتُ مَجْلِسَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَكَلْتُ مَا أَكَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَنَعْتُ مَا صَنَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[415,415,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏زُهْرَةُ بْنُ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَنَّهُ حَدَّثَهُ قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏بِمِنًى ‏ ‏يَقُولُ يَا أَيُّهَا النَّاسُ إِنِّي أُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ فَلْيُرَابِطْ امْرُؤٌ كَيْفَ شَاءَ هَلْ بَلَّغْتُ قَالُوا نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ ‏","","",""],[416,416,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏يَعْنِي مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ إِبْرَاهِيمَ الْبَاهِلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي ذُبَابٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏صَلَّى ‏ ‏بِمِنًى ‏ ‏أَرْبَعَ رَكَعَاتٍ فَأَنْكَرَهُ النَّاسُ عَلَيْهِ فَقَالَ يَا أَيُّهَا النَّاسُ إِنِّي ‏ ‏تَأَهَّلْتُ ‏ ‏بِمَكَّةَ ‏ ‏مُنْذُ قَدِمْتُ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏تَأَهَّلَ ‏ ‏فِي بَلَدٍ فَلْيُصَلِّ صَلَاةَ الْمُقِيمِ ‏","","",""],[417,417,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ وَرْدَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْطُبُ عَلَى الْمِنْبَرِ وَهُوَ يَقُولُ كُنْتُ أَبْتَاعُ التَّمْرَ مِنْ بَطْنٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏يُقَالُ لَهُمْ ‏ ‏بَنُو قَيْنُقَاعَ ‏ ‏فَأَبِيعُهُ بِرِبْحٍ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏إِذَا اشْتَرَيْتَ فَاكْتَلْ وَإِذَا بِعْتَ فَكِلْ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ وَرْدَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[418,418,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ ‏ ‏بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ لَمْ يَضُرَّهُ شَيْءٌ ‏","","",""],[419,419,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَعْلَمُ كَلِمَةً لَا يَقُولُهَا عَبْدٌ حَقًّا مِنْ قَلْبِهِ إِلَّا حُرِّمَ عَلَى النَّارِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا أُحَدِّثُكَ مَا هِيَ هِيَ كَلِمَةُ الْإِخْلَاصِ الَّتِي أَعَزَّ اللَّهُ تَبَارَكَ وَتَعَالَى بِهَا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ وَهِيَ كَلِمَةُ التَّقْوَى الَّتِي ‏ ‏أَلَاصَ ‏ ‏عَلَيْهَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّهُ ‏ ‏أَبَا طَالِبٍ ‏ ‏عِنْدَ الْمَوْتِ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[420,420,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏زَيْدَ بْنَ خَالِدٍ الْجُهَنِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قُلْتُ أَرَأَيْتَ إِذَا جَامَعَ امْرَأَتَهُ وَلَمْ ‏ ‏يُمْنِ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏يَتَوَضَّأُ كَمَا يَتَوَضَّأُ لِلصَّلَاةِ وَيَغْسِلُ ذَكَرَهُ وَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُ ‏ ‏عَنْ ذَلِكَ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَالزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏وَطَلْحَةَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏وَأُبَيَّ بْنَ كَعْبٍ ‏ ‏فَأَمَرُوهُ بِذَلِكَ ‏","","",""],[421,421,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ أَنَسٍ ‏ ‏يَقُولُ ‏ { ‏نَرْفَعُ دَرَجَاتٍ مَنْ نَشَاءُ ‏} ‏قَالَ بِالْعِلْمِ ‏ ‏قُلْتُ مَنْ حَدَّثَكَ قَالَ زَعَمَ ذَاكَ ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏","","",""],[422,422,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏مَسَرَّةُ بْنُ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي كَبْشَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي صَلَّيْتُ فَلَمْ أَدْرِ ‏ ‏أَشَفَعْتُ ‏ ‏أَمْ ‏ ‏أَوْتَرْتُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّايَ وَأَنْ يَتَلَعَّبَ بِكُمْ الشَّيْطَانُ فِي صَلَاتِكُمْ مَنْ صَلَّى مِنْكُمْ فَلَمْ يَدْرِ أَشَفَعَ أَوْ أَوْتَرَ فَلْيَسْجُدْ سَجْدَتَيْنِ فَإِنَّهُمَا تَمَامُ صَلَاتِهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏وَزِيَادُ بْنُ أَيُّوبَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَوَّارٌ أَبُو عُمَارَةَ الرَّمْلِيُّ ‏ ‏عَنْ ‏ ‏مَسِيرَةَ بْنِ مَعْبَدٍ ‏ ‏قَالَ صَلَّى بِنَا ‏ ‏يَزِيدُ بْنُ أَبِي كَبْشَةَ ‏ ‏الْعَصْرَ فَانْصَرَفَ إِلَيْنَا بَعْدَ صَلَاتِهِ فَقَالَ إِنِّي صَلَّيْتُ مَعَ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏فَسَجَدَ مِثْلَ هَاتَيْنِ السَّجْدَتَيْنِ ثُمَّ انْصَرَفَ إِلَيْنَا فَأَعْلَمَنَا أَنَّهُ صَلَّى مَعَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَحَدَّثَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ نَحْوَهُ ‏","","",""],[423,423,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُغِيرَةَ بْنَ مُسْلِمٍ أَبَا سَلَمَةَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَشْرَفَ ‏ ‏عَلَى أَصْحَابِهِ وَهُوَ مَحْصُورٌ فَقَالَ عَلَامَ تَقْتُلُونِي فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ رَجُلٌ زَنَى بَعْدَ إِحْصَانِهِ فَعَلَيْهِ ‏ ‏الرَّجْمُ ‏ ‏أَوْ قَتَلَ عَمْدًا فَعَلَيْهِ ‏ ‏الْقَوَدُ ‏ ‏أَوْ ارْتَدَّ بَعْدَ إِسْلَامِهِ فَعَلَيْهِ الْقَتْلُ ‏ ‏فَوَاللَّهِ مَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ وَلَا قَتَلْتُ أَحَدًا ‏ ‏فَأُقِيدَ ‏ ‏نَفْسِي مِنْهُ وَلَا ارْتَدَدْتُ مُنْذُ أَسْلَمْتُ إِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[424,424,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَبِيلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ عَبْدِ اللَّهِ الْبَرْدَادِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏أَنَّهُ جَاءَ يَسْتَأْذِنُ عَلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَذِنَ لَهُ وَبِيَدِهِ عَصَاهُ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا ‏ ‏كَعْبُ ‏ ‏إِنَّ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏تُوُفِّيَ وَتَرَكَ مَالًا فَمَا ‏ ‏تَرَى فِيهِ فَقَالَ إِنْ كَانَ يَصِلُ فِيهِ حَقَّ اللَّهِ فَلَا بَأْسَ عَلَيْهِ فَرَفَعَ ‏ ‏أَبُو ذَرٍّ ‏ ‏عَصَاهُ فَضَرَبَ ‏ ‏كَعْبًا ‏ ‏وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أُحِبُّ لَوْ أَنَّ لِي هَذَا الْجَبَلَ ذَهَبًا أُنْفِقُهُ وَيُتَقَبَّلُ مِنِّي أَذَرُ خَلْفِي مِنْهُ سِتَّ ‏ ‏أَوَاقٍ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ يَا ‏ ‏عُثْمَانُ ‏ ‏أَسَمِعْتَهُ ثَلَاثَ مَرَّاتٍ قَالَ نَعَمْ ‏","","",""],[425,425,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ الْقَاصُّ ‏ ‏عَنْ ‏ ‏هَانِئٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِذَا وَقَفَ عَلَى قَبْرٍ بَكَى حَتَّى يَبُلَّ لِحْيَتَهُ ‏ ‏فَقِيلَ لَهُ تَذْكُرُ الْجَنَّةَ وَالنَّارَ فَلَا تَبْكِي ‏ ‏وَتَبْكِي مِنْ هَذَا فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْقَبْرُ أَوَّلُ مَنَازِلِ الْآخِرَةِ فَإِنْ يَنْجُ مِنْهُ فَمَا بَعْدَهُ أَيْسَرُ مِنْهُ وَإِنْ لَمْ يَنْجُ مِنْهُ فَمَا بَعْدَهُ أَشَدُّ مِنْهُ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ مَا رَأَيْتُ ‏ ‏مَنْظَرًا قَطُّ إِلَّا وَالْقَبْرُ أَفْظَعُ مِنْهُ ‏","","",""],[426,426,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ ‏ ‏وَمَا إِخَالُهُ يُتَّهَمُ عَلَيْنَا ‏ ‏قَالَ أَصَابَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رُعَافٌ ‏ ‏سَنَةَ ‏ ‏الرُّعَافِ ‏ ‏حَتَّى تَخَلَّفَ عَنْ الْحَجِّ وَأَوْصَى فَدَخَلَ عَلَيْهِ رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ اسْتَخْلِفْ قَالَ وَقَالُوهُ قَالَ نَعَمْ قَالَ مَنْ هُوَ قَالَ فَسَكَتَ قَالَ ثُمَّ دَخَلَ عَلَيْهِ رَجُلٌ آخَرُ فَقَالَ لَهُ مِثْلَ مَا قَالَ لَهُ الْأَوَّلُ وَرَدَّ عَلَيْهِ نَحْوَ ذَلِكَ قَالَ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالُوا ‏ ‏الزُّبَيْرَ ‏ ‏قَالَ نَعَمْ قَالَ أَمَا وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنْ كَانَ لَخَيْرَهُمْ مَا عَلِمْتُ وَأَحَبَّهُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَاه ‏ ‏سُوَيْدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏بِإِسْنَادِهِ ‏ ‏مِثْلَهُ ‏","","",""],[427,427,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عِمْرَانَ بْنِ مَنَّاحٍ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏أَبَانُ بْنُ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏جَنَازَةً فَقَامَ لَهَا وَقَالَ رَأَى ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏جَنَازَةً فَقَامَ لَهَا ثُمَّ حَدَّثَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى جَنَازَةً فَقَامَ لَهَا ‏","","",""],[428,428,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَأَلَ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ قُلْتُ أَرَأَيْتَ إِذَا جَامَعَ الرَّجُلُ امْرَأَتَهُ وَلَمْ ‏ ‏يُمْنِ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَتَوَضَّأُ كَمَا يَتَوَضَّأُ لِلصَّلَاةِ وَيَغْسِلُ ذَكَرَهُ قَالَ وَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُ ‏ ‏عَنْ ذَلِكَ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏وَالزُّبَيْرَ ‏ ‏وَطَلْحَةَ ‏ ‏وَأُبَيَّ بْنَ كَعْبٍ ‏ ‏فَأَمَرُوهُ بِذَلِكَ ‏","","",""],[429,429,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُعَاذُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏أَتَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ جَالِسٌ فِي الْمَقَاعِدِ فَتَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي هَذَا الْمَجْلِسِ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا ثُمَّ أَتَى الْمَسْجِدَ فَرَكَعَ فِيهِ رَكْعَتَيْنِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا تَغْتَرُّوا ‏","","",""],[430,430,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ حَفْصٍ بْنِ عُمَرَ التَّيْمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَمِّي ‏ ‏عُبَيْدَ اللَّهِ بْنَ عُمَرَ بْنِ مُوسَى ‏ ‏يَقُولُ ‏ ‏كُنْتُ عِنْدَ ‏ ‏سُلَيْمَانَ بْنِ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَدَخَلَ شَيْخٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ ‏ ‏سُلَيْمَانُ ‏ ‏انْظُرْ إِلَى الشَّيْخِ فَأَقْعِدْهُ مَقْعَدًا صَالِحًا فَإِنَّ ‏ ‏لِقُرَيْشٍ ‏ ‏حَقًّا فَقُلْتُ أَيُّهَا الْأَمِيرُ أَلَا أُحَدِّثُكَ حَدِيثًا بَلَغَنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَلَى قَالَ قُلْتُ لَهُ بَلَغَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَهَانَ ‏ ‏قُرَيْشًا ‏ ‏أَهَانَهُ اللَّهُ ‏ ‏قَالَ ‏ ‏سُبْحَانَ اللَّهِ مَا أَحْسَنَ هَذَا مَنْ حَدَّثَكَ هَذَا قَالَ قُلْتُ ‏ ‏حَدَّثَنِيهِ ‏ ‏رَبِيعَةُ بْنُ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏أَبِي ‏ ‏يَا بُنَيَّ إِنْ وَلِيتَ مِنْ أَمْرِ النَّاسِ شَيْئًا فَأَكْرِمْ ‏ ‏قُرَيْشًا ‏ ‏فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ أَهَانَ ‏ ‏قُرَيْشًا ‏ ‏أَهَانَهُ اللَّهُ ‏","","",""],[431,431,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبَانَ الْوَرَّاقُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ أَبِي الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏حِينَ حُصِرَ إِنَّ عِنْدِي ‏ ‏نَجَائِبَ ‏ ‏قَدْ أَعْدَدْتُهَا لَكَ فَهَلْ لَكَ أَنْ تَحَوَّلَ إِلَى ‏ ‏مَكَّةَ ‏ ‏فَيَأْتِيَكَ مَنْ أَرَادَ أَنْ يَأْتِيَكَ قَالَ لَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُلْحَدُ ‏ ‏بِمَكَّةَ ‏ ‏كَبْشٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏اسْمُهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَلَيْهِ مِثْلُ نِصْفِ ‏ ‏أَوْزَارِ ‏ ‏النَّاسِ ‏","","",""],[432,432,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏وَيَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْكِحُ ‏ ‏الْمُحْرِمُ ‏ ‏وَلَا ‏ ‏يُنْكِحُ ‏ ‏وَلَا يَخْطُبُ ‏","","",""],[433,433,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَخْطُبُ عَلَى مِنْبَرِهِ إِنِّي مُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يَمْنَعُنِي أَنْ أُحَدِّثَكُمْ بِهِ إِلَّا الضِّنُّ بِكُمْ ‏ ‏إِنِّي ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏حَرَسُ لَيْلَةٍ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنْ أَلْفِ لَيْلَةٍ يُقَامُ لَيْلُهَا وَيُصَامُ نَهَارُهَا ‏","","",""],[434,434,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ الْعَنْبَرِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ ‏","","",""],[435,435,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ مُوسَى ‏ ‏حَدَّثَنِي ‏ ‏نُبَيْهُ بْنُ وَهْبٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏رَمِدَتْ عَيْنُهُ وَهُوَ مُحْرِمٌ فَأَرَادَ أَنْ يُكَحِّلَهَا فَنَهَاهُ ‏ ‏أَبَانُ بْنُ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَأَمَرَهُ أَنْ يُضَمِّدَهَا ‏ ‏بِالصَّبِرِ ‏ ‏وَزَعَمَ أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ فَعَلَ ذَلِكَ ‏","","",""],[436,436,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏أَرَادَ أَنْ يُزَوِّجَ ابْنَهُ وَهُوَ مُحْرِمٌ فَنَهَاهُ ‏ ‏أَبَانُ ‏ ‏وَزَعَمَ أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُحْرِمُ لَا يَنْكِحُ وَلَا يُنْكِحُ ‏","","",""],[437,437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَبَاحٍ ‏ ‏قَالَ ‏ ‏زَوَّجَنِي أَهْلِي أَمَةً لَهُمْ رُومِيَّةً وَلَدَتْ لِي غُلَامًا أَسْوَدَ فَعَلِقَهَا عَبْدٌ رُومِيٌّ يُقَالُ لَهُ ‏ ‏يُوحَنَّسُ ‏ ‏فَجَعَلَ يُرَاطِنُهَا بِالرُّومِيَّةِ فَحَمَلَتْ وَقَدْ كَانَتْ وَلَدَتْ لِي غُلَامًا أَسْوَدَ مِثْلِي فَجَاءَتْ بِغُلَامٍ وَكَأَنَّهُ ‏ ‏وَزَغَةٌ ‏ ‏مِنْ ‏ ‏الْوَزَغَاتِ ‏ ‏فَقُلْتُ لَهَا مَا هَذَا فَقَالَتْ هُوَ مِنْ ‏ ‏يُوحَنَّسَ ‏ ‏فَسَأَلْتُ ‏ ‏يُوحَنَّسَ ‏ ‏فَاعْتَرَفَ فَأَتَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَأَرْسَلَ إِلَيْهِمَا فَسَأَلَهُمَا ثُمَّ قَالَ ‏ ‏سَأَقْضِي بَيْنَكُمَا بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏فَأَلْحَقَهُ بِي قَالَ فَجَلَدَهُمَا فَوَلَدَتْ لِي بَعْدُ غُلَامًا أَسْوَدَ ‏","","",""],[438,438,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي الدَّارِ وَهُوَ مَحْصُورٌ قَالَ وَكُنَّا نَدْخُلُ مَدْخَلًا إِذَا دَخَلْنَاهُ سَمِعْنَا كَلَامَ مَنْ عَلَى الْبَلَاطِ قَالَ فَدَخَلَ ‏ ‏عُثْمَانُ ‏ ‏يَوْمًا لِحَاجَةٍ فَخَرَجَ إِلَيْنَا مُنْتَقِعًا لَوْنُهُ فَقَالَ إِنَّهُمْ لَيَتَوَعَّدُونِي بِالْقَتْلِ ‏ ‏آنِفًا ‏ ‏قَالَ قُلْنَا ‏ ‏يَكْفِيكَهُمُ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ فَقَالَ وَبِمَ يَقْتُلُونِي فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا فِي إِحْدَى ثَلَاثٍ رَجُلٌ كَفَرَ بَعْدَ إِسْلَامِهِ أَوْ زَنَى بَعْدَ ‏ ‏إِحْصَانِهِ ‏ ‏أَوْ قَتَلَ نَفْسًا بِغَيْرِ ‏ ‏نَفْسٍ ‏ ‏فَوَاللَّهِ مَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ وَلَا تَمَنَّيْتُ بَدَلًا بِدِينِي مُذْ هَدَانِي اللَّهُ عَزَّ وَجَلَّ وَلَا قَتَلْتُ نَفْسًا فَبِمَ يَقْتُلُونِي ‏","","",""],[439,439,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏ح ‏ ‏وَسُرَيْجٌ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏حُسَيْنُ ‏ ‏ابْنُ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ مَا يَمْنَعُنِي أَنْ أُحَدِّثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ لَا أَكُونَ أَوْعَى أَصْحَابِهِ عَنْهُ وَلَكِنِّي أَشْهَدُ لَسَمِعْتُهُ يَقُولُ ‏ ‏مَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏ ‏وَقَالَ ‏ ‏حُسَيْنٌ ‏ ‏أَوْعَى ‏ ‏صَحَابَتِهِ عَنْهُ ‏","","",""],[440,440,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏زُهْرَةُ بْنُ مَعْبَدٍ الْقُرَشِيُّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏عَلَى الْمِنْبَرِ أَيُّهَا النَّاسُ إِنِّي كَتَمْتُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَرَاهِيَةَ تَفَرُّقِكُمْ عَنِّي ثُمَّ بَدَا لِي أَنْ أُحَدِّثَكُمُوهُ لِيَخْتَارَ امْرُؤٌ لِنَفْسِهِ مَا بَدَا لَهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ تَعَالَى خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ مِنْ الْمَنَازِلِ ‏","","",""],[441,441,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمٍ يَخْرُجُ مِنْ بَيْتِهِ يُرِيدُ سَفَرًا أَوْ غَيْرَهُ فَقَالَ حِينَ يَخْرُجُ بِسْمِ اللَّهِ آمَنْتُ بِاللَّهِ اعْتَصَمْتُ بِاللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ إِلَّا رُزِقَ خَيْرَ ذَلِكَ الْمَخْرَجِ ‏ ‏وَصُرِفَ ‏ ‏عَنْهُ شَرُّ ذَلِكَ الْمَخْرَجِ ‏","","",""],[442,442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ غَسْلًا ‏","","",""],[443,443,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو صَخْرَةَ جَامِعُ بْنُ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏فِي مَسْجِدِ ‏ ‏الْبَصْرَةِ ‏ ‏وَأَنَا قَائِمٌ مَعَهُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ فَالصَّلَوَاتُ الْخَمْسُ ‏ ‏كَفَّارَةٌ ‏ ‏لِمَا بَيْنَهُنَّ ‏","","",""],[444,444,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ فِي أَوَّلِ يَوْمِهِ أَوْ فِي أَوَّلِ لَيْلَتِهِ بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ ثَلَاثَ مَرَّاتٍ لَمْ يَضُرَّهُ شَيْءٌ فِي ذَلِكَ الْيَوْمِ أَوْ فِي تِلْكَ اللَّيْلَةِ ‏","","",""],[445,445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو سِنَانٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مَوْهَبٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اقْضِ بَيْنَ النَّاسِ فَقَالَ لَا أَقْضِي بَيْنَ اثْنَيْنِ وَلَا أَؤُمُّ رَجُلَيْنِ أَمَا سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ عَاذَ بِاللَّهِ فَقَدْ عَاذَ بِمَعَاذٍ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَلَى ‏ ‏قَالَ فَإِنِّي أَعُوذُ بِاللَّهِ أَنْ تَسْتَعْمِلَنِي فَأَعْفَاهُ وَقَالَ لَا تُخْبِرْ بِهَذَا أَحَدًا ‏","","",""],[446,446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِهِ ‏","","",""],[447,447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَاه ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏سَنَةَ سِتٍّ وَعِشْرِينَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زُهْرَةَ بْنِ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏أَيُّهَا النَّاسُ هَجِّرُوا فَإِنِّي مُهَجِّرٌ فَهَجَّرَ النَّاسُ ثُمَّ قَالَ أَيُّهَا النَّاسُ إِنِّي مُحَدِّثُكُمْ بِحَدِيثٍ مَا تَكَلَّمْتُ بِهِ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى يَوْمِي هَذَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رِبَاطَ يَوْمٍ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنْ أَلْفِ يَوْمٍ مِمَّا سِوَاهُ فَلْيُرَابِطْ امْرُؤٌ حَيْثُ شَاءَ هَلْ بَلَّغْتُكُمْ قَالُوا نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ ‏","","",""],[448,448,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏حَدَّثَنِي ‏ ‏شَقِيقُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَاعِدًا فِي الْمَقَاعِدِ فَدَعَا بِوَضُوءٍ فَتَوَضَّأَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فِي مَقْعَدِي هَذَا ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا ثُمَّ قَامَ فَرَكَعَ رَكْعَتَيْنِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَغْتَرُّوا ‏","","",""],[449,449,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَرْطَاةُ يَعْنِي ابْنَ الْمُنْذِرِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو عَوْنٍ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لِابْنِ مَسْعُودٍ ‏ ‏هَلْ أَنْتَ مُنْتَهٍ عَمَّا بَلَغَنِي عَنْكَ فَاعْتَذَرَ بَعْضَ الْعُذْرِ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَيْحَكَ ‏ ‏إِنِّي قَدْ سَمِعْتُ وَحَفِظْتُ وَلَيْسَ كَمَا سَمِعْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيُقْتَلُ أَمِيرٌ ‏ ‏وَيَنْتَزِي مُنْتَزٍ ‏ ‏وَإِنِّي أَنَا الْمَقْتُولُ وَلَيْسَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّمَا قَتَلَ ‏ ‏عُمَرَ ‏ ‏وَاحِدٌ وَإِنَّهُ يُجْتَمَعُ عَلَيَّ ‏","","",""],[450,450,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ لَهُ ابْنَ أَخِي أَدْرَكْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقُلْتُ لَهُ لَا وَلَكِنْ خَلَصَ إِلَيَّ مِنْ عِلْمِهِ وَالْيَقِينِ مَا يَخْلُصُ إِلَى الْعَذْرَاءِ فِي سِتْرِهَا قَالَ فَتَشَهَّدَ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَقِّ فَكُنْتُ مِمَّنْ اسْتَجَابَ لِلَّهِ وَلِرَسُولِهِ وَآمَنَ بِمَا بُعِثَ بِهِ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ هَاجَرْتُ الْهِجْرَتَيْنِ كَمَا قُلْتُ وَنِلْتُ ‏ ‏صِهْرَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَاللَّهِ مَا عَصَيْتُهُ وَلَا غَشَشْتُهُ حَتَّى تَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[451,451,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ ‏ ‏أَنَّهُ حَدَّثَهُ عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ مَحْصُورٌ فَقَالَ إِنَّكَ إِمَامُ الْعَامَّةِ وَقَدْ نَزَلَ بِكَ مَا ‏ ‏تَرَى وَإِنِّي أَعْرِضُ عَلَيْكَ خِصَالًا ثَلَاثًا اخْتَرْ إِحْدَاهُنَّ إِمَّا أَنْ تَخْرُجَ فَتُقَاتِلَهُمْ فَإِنَّ مَعَكَ عَدَدًا وَقُوَّةً وَأَنْتَ عَلَى الْحَقِّ وَهُمْ عَلَى الْبَاطِلِ وَإِمَّا أَنْ نَخْرِقَ لَكَ بَابًا سِوَى الْبَابِ الَّذِي هُمْ عَلَيْهِ فَتَقْعُدَ عَلَى رَوَاحِلِكَ فَتَلْحَقَ ‏ ‏بِمَكَّةَ ‏ ‏فَإِنَّهُمْ لَنْ يَسْتَحِلُّوكَ وَأَنْتَ بِهَا وَإِمَّا أَنْ تَلْحَقَ ‏ ‏بِالشَّامِ ‏ ‏فَإِنَّهُمْ أَهْلُ ‏ ‏الشَّامِ ‏ ‏وَفِيهِمْ ‏ ‏مُعَاوِيَةُ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَمَّا أَنْ أَخْرُجَ فَأُقَاتِلَ فَلَنْ أَكُونَ أَوَّلَ مَنْ خَلَفَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أُمَّتِهِ بِسَفْكِ الدِّمَاءِ وَأَمَّا أَنْ أَخْرُجَ إِلَى ‏ ‏مَكَّةَ ‏ ‏فَإِنَّهُمْ لَنْ يَسْتَحِلُّونِي بِهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُلْحِدُ ‏ ‏رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏بِمَكَّةَ ‏ ‏يَكُونُ عَلَيْهِ نِصْفُ عَذَابِ الْعَالَمِ فَلَنْ أَكُونَ أَنَا إِيَّاهُ وَأَمَّا أَنْ أَلْحَقَ ‏ ‏بِالشَّامِ ‏ ‏فَإِنَّهُمْ أَهْلُ ‏ ‏الشَّامِ ‏ ‏وَفِيهِمْ ‏ ‏مُعَاوِيَةُ ‏ ‏فَلَنْ أُفَارِقَ دَارَ هِجْرَتِي وَمُجَاوَرَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَاه ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ يُلْحِدُ ‏","","",""],[452,452,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏وَنَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ الرَّحْمَنِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ فَأَسْبَغَ الْوُضُوءَ ثُمَّ مَشَى إِلَى صَلَاةٍ مَكْتُوبَةٍ فَصَلَّاهَا غُفِرَ لَهُ ذَنْبُهُ ‏","","",""],[453,453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَغْتَسِلُ كُلَّ يَوْمٍ مَرَّةً مِنْ مُنْذُ أَسْلَمَ فَوَضَعْتُ ‏ ‏وَضُوءًا ‏ ‏لَهُ ذَاتَ يَوْمٍ لِلصَّلَاةِ فَلَمَّا تَوَضَّأَ قَالَ إِنِّي أَرَدْتُ أَنْ أُحَدِّثَكُمْ بِحَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏بَدَا ‏ ‏لِي أَنْ لَا أُحَدِّثَكُمُوهُ فَقَالَ ‏ ‏الْحَكَمُ بْنُ أَبِي الْعَاصِ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ إِنْ كَانَ خَيْرًا فَنَأْخُذُ بِهِ أَوْ شَرًّا ‏ ‏فَنَتَّقِيهِ قَالَ فَقَالَ فَإِنِّي مُحَدِّثُكُمْ بِهِ تَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْوُضُوءَ ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ هَذَا الْوُضُوءَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَامَ إِلَى الصَّلَاةِ فَأَتَمَّ رُكُوعَهَا وَسُجُودَهَا كَفَّرَتْ عَنْهُ مَا بَيْنَهَا وَبَيْنَ الصَّلَاةِ الْأُخْرَى مَا لَمْ يُصِبْ مَقْتَلَةً ‏ ‏يَعْنِي كَبِيرَةً ‏","","",""],[454,454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ فَرُّوخَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَدْخَلَ اللَّهُ الْجَنَّةَ رَجُلًا كَانَ سَهْلًا قَاضِيًا ‏ ‏وَمُقْتَضِيًا ‏ ‏وَبَائِعًا وَمُشْتَرِيًا ‏","","",""],[455,455,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّ الْمُؤَذِّنَ أَذَّنَ لِصَلَاةِ الْعَصْرِ قَالَ فَدَعَا ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِطَهُورٍ فَتَطَهَّرَ قَالَ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَطَهَّرَ كَمَا أُمِرَ وَصَلَّى كَمَا أُمِرَ كُفِّرَتْ عَنْهُ ذُنُوبُهُ فَاسْتَشْهَدَ عَلَى ذَلِكَ أَرْبَعَةً مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَشَهِدُوا لَهُ بِذَلِكَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[456,456,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْأَشْجَعِيِّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏عُثْمَانُ ‏ ‏الْمَقَاعِدَ ‏ ‏فَدَعَا ‏ ‏بِوَضُوءٍ ‏ ‏فَتَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ وَرِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا يَتَوَضَّأُ يَا هَؤُلَاءِ أَكَذَاكَ قَالُوا نَعَمْ لِنَفَرٍ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَهُ ‏","","",""],[457,457,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ ‏ ‏دَعَا بِمَاءٍ فَتَوَضَّأَ عِنْدَ ‏ ‏الْمَقَاعِدِ فَتَوَضَّأَ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ ‏ ‏لِأَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ رَأَيْتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ هَذَا قَالُوا نَعَمْ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏هَذَا ‏ ‏الْعَدَنِيُّ كَانَ ‏ ‏بِمَكَّةَ ‏ ‏مُسْتَمْلِيَ ‏ ‏ابْنِ عُيَيْنَةَ ‏","","",""],[458,458,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ الرَّحْمَنِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏دَعَا بِوَضُوءٍ وَهُوَ عَلَى بَابِ الْمَسْجِدِ فَغَسَلَ يَدَيْهِ ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مَرَّاتٍ ثُمَّ مَسَحَ بِرَأْسِهِ وَأَمَرَّ بِيَدَيْهِ عَلَى ظَاهِرِ أُذُنَيْهِ ثُمَّ مَرَّ بِهِمَا عَلَى لِحْيَتِهِ ثُمَّ غَسَلَ رِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثَلَاثَ مَرَّاتٍ ثُمَّ قَامَ فَرَكَعَ رَكْعَتَيْنِ ثُمَّ قَالَ تَوَضَّأْتُ لَكُمْ كَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ثُمَّ رَكَعْتُ رَكْعَتَيْنِ كَمَا رَأَيْتُهُ رَكَعَ قَالَ ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ فَرَغَ مِنْ رَكْعَتَيْهِ ‏ ‏مَنْ تَوَضَّأَ كَمَا تَوَضَّأْتُ ثُمَّ رَكَعَ رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا كَانَ بَيْنَهُمَا وَبَيْنَ صَلَاتِهِ بِالْأَمْسِ ‏","","",""],[459,459,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏الْوَلِيدَ بْنَ عُقْبَةَ ‏ ‏فَقَالَ لَهُ ‏ ‏الْوَلِيدُ ‏ ‏مَا لِي أَرَاكَ قَدْ جَفَوْتَ أَمِيرَ الْمُؤْمِنِينَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَبْلِغْهُ أَنِّي لَمْ أَفِرَّ يَوْمَ ‏ ‏عَيْنَيْنِ ‏ ‏قَالَ ‏ ‏عَاصِمٌ ‏ ‏يَقُولُ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَلَمْ أَتَخَلَّفْ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏وَلَمْ أَتْرُكْ سُنَّةَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَانْطَلَقَ فَخَبَّرَ ذَلِكَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَقَالَ أَمَّا قَوْلُهُ إِنِّي لَمْ أَفِرَّ يَوْمَ ‏ ‏عَيْنَيْنَ ‏ ‏فَكَيْفَ يُعَيِّرُنِي بِذَنْبٍ وَقَدْ عَفَا اللَّهُ عَنْهُ فَقَالَ ‏ { ‏إِنَّ الَّذِينَ تَوَلَّوْا مِنْكُمْ يَوْمَ الْتَقَى الْجَمْعَانِ إِنَّمَا اسْتَزَلَّهُمْ الشَّيْطَانُ بِبَعْضِ مَا كَسَبُوا وَلَقَدْ عَفَا اللَّهُ عَنْهُمْ ‏} ‏وَأَمَّا قَوْلُهُ إِنِّي تَخَلَّفْتُ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَإِنِّي كُنْتُ أُمَرِّضُ ‏ ‏رُقَيَّةَ بِنْتَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ مَاتَتْ وَقَدْ ‏ ‏ضَرَبَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَهْمِي وَمَنْ ضَرَبَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَهْمِهِ فَقَدْ شَهِدَ وَأَمَّا قَوْلُهُ إِنِّي لَمْ أَتْرُكْ سُنَّةَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَإِنِّي لَا أُطِيقُهَا وَلَا هُوَ فَأْتِهِ فَحَدِّثْهُ بِذَلِكَ ‏","","",""],[460,460,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ يَعْنِي عُثْمَانَ بْنَ حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ كَانَ كَقِيَامِ نِصْفِ لَيْلَةٍ وَمَنْ صَلَّى الْعِشَاءَ وَالْفَجْرَ فِي جَمَاعَةٍ كَانَ كَقِيَامِ لَيْلَةٍ ‏","","",""],[461,461,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏قَالَ ‏ ‏أَرَادَ ‏ ‏ابْنُ مَعْمَرٍ ‏ ‏أَنْ يُنْكِحَ ابْنَهُ ‏ ‏ابْنَةَ شَيْبَةَ بْنِ جُبَيْرٍ ‏ ‏فَبَعَثَنِي إِلَى ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ أَمِيرُ الْمَوْسِمِ فَأَتَيْتُهُ فَقُلْتُ لَهُ إِنَّ أَخَاكَ أَرَادَ أَنْ يُنْكِحَ ابْنَهُ فَأَرَادَ أَنْ يُشْهِدَكَ ذَاكَ فَقَالَ أَلَا أُرَاهُ عِرَاقِيًّا جَافِيًا ‏ ‏إِنَّ الْمُحْرِمَ لَا يَنْكِحُ وَلَا يُنْكِحُ ‏ ‏ثُمَّ ‏ ‏حَدَّثَ عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِمِثْلِهِ يَرْفَعُهُ ‏","","",""],[462,462,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏تَوَضَّأَ ‏ ‏بِالْمَقَاعِدِ ‏ ‏فَغَسَلَ ثَلَاثًا ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ وُضُوئِي هَذَا ثُمَّ قَامَ إِلَى الصَّلَاةِ سَقَطَتْ خَطَايَاهُ ‏ ‏يَعْنِي مِنْ وَجْهِهِ وَيَدَيْهِ وَرِجْلَيْهِ وَرَأْسِهِ ‏","","",""],[463,463,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏قَالَ ‏ ‏اشْتَكَى ‏ ‏عُمَرُ بْنُ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ عَيْنَيْهِ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَهُوَ أَمِيرٌ ‏ ‏مَا يَصْنَعُ بِهِمَا قَالَ قَالَ ‏ ‏ضَمَّدَهُمَا ‏ ‏بِالصَّبِرِ ‏ ‏فَإِنِّي ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُحَدِّثُ ذَلِكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[464,464,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ بْنُ مُوسَى أَبُو صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عِمْرَانَ بْنِ مَنَّاحٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ ‏ ‏رَأَى جَنَازَةً مُقْبِلَةً فَلَمَّا رَآهَا قَامَ وَقَالَ رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏يَفْعَلُ ذَلِكَ وَأَخْبَرَنِي أَنَّهُ رَأَى ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[465,465,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْكِحُ الْمُحْرِمُ وَلَا يَخْطُبُ ‏","","",""],[466,466,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى بْنِ عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏الْحَجَبَةِ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ حَدَّثَ عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ ‏ ‏أَوْ قَالَ ‏ ‏فِي الْمُحْرِمِ إِذَا اشْتَكَى عَيْنَهُ أَنْ يُضَمِّدَهَا ‏ ‏بِالصَّبِرِ ‏","","",""],[467,467,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ ‏","","",""],[468,468,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفُ بْنُ أَبِي جَمِيلَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ الْفَارِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعُثْمَانَ ‏ ‏مَا حَمَلَكُمْ عَلَى أَنْ عَمَدْتُمْ إِلَى سُورَةِ ‏ ‏الْأَنْفَالِ ‏ ‏وَهِيَ مِنْ ‏ ‏الْمَثَانِي ‏ ‏وَإِلَى سُورَةِ ‏ ‏بَرَاءَةٌ ‏ ‏وَهِيَ مِنْ ‏ ‏الْمِئِينَ فَقَرَنْتُمْ بَيْنَهُمَا وَلَمْ تَكْتُبُوا بَيْنَهُمَا سَطْرَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏فَوَضَعْتُمُوهَا فِي ‏ ‏السَّبْعِ الطِّوَالِ ‏ ‏فَمَا حَمَلَكُمْ عَلَى ذَلِكَ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا يَأْتِي عَلَيْهِ الزَّمَانُ وَهُوَ يُنْزَلُ عَلَيْهِ مِنْ السُّوَرِ ذَوَاتِ الْعَدَدِ فَكَانَ إِذَا أُنْزِلَ عَلَيْهِ الشَّيْءُ دَعَا بَعْضَ مَنْ يَكْتُبُ لَهُ فَيَقُولُ ‏ ‏ضَعُوا هَذِهِ فِي السُّورَةِ الَّتِي يُذْكَرُ فِيهَا كَذَا وَكَذَا وَإِذَا أُنْزِلَتْ عَلَيْهِ الْآيَاتُ قَالَ ضَعُوا هَذِهِ الْآيَاتِ فِي السُّورَةِ الَّتِي يُذْكَرُ فِيهَا كَذَا وَكَذَا وَإِذَا أُنْزِلَتْ عَلَيْهِ الْآيَةُ قَالَ ضَعُوا هَذِهِ الْآيَةَ فِي السُّورَةِ الَّتِي يُذْكَرُ فِيهَا كَذَا وَكَذَا وَكَانَتْ سُورَةُ ‏ ‏الْأَنْفَالِ ‏ ‏مِنْ أَوَائِلِ مَا نَزَلَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَكَانَتْ سُورَةُ ‏ ‏بَرَاءَةٌ ‏ ‏مِنْ أَوَاخِرِ مَا أُنْزِلَ مِنْ الْقُرْآنِ قَالَ فَكَانَتْ قِصَّتُهَا شَبِيهًا بِقِصَّتِهَا فَظَنَنَّا أَنَّهَا مِنْهَا وَقُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يُبَيِّنْ لَنَا أَنَّهَا مِنْهَا فَمِنْ أَجْلِ ذَلِكَ ‏ ‏قَرَنْتُ ‏ ‏بَيْنَهُمَا وَلَمْ أَكْتُبْ بَيْنَهُمَا سَطْرَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏وَوَضَعْتُهَا فِي ‏ ‏السَّبْعِ الطِّوَالِ ‏","","",""],[469,469,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَشُعْبَةَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أَفْضَلُكُمْ ‏ ‏وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏خَيْرُكُمْ ‏ ‏مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ ‏","","",""],[470,470,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏قَالَ قَالَ ‏ ‏قَيْسٌ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو سَهْلَةَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏قَالَ يَوْمَ الدَّارِ حِينَ ‏ ‏حُصِرَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ إِلَيَّ ‏ ‏عَهْدًا ‏ ‏فَأَنَا صَابِرٌ عَلَيْهِ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏فَكَانُوا يَرَوْنَهُ ذَلِكَ الْيَوْمَ ‏","","",""],[471,471,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبَاحٌ ‏ ‏قَالَ ‏ ‏زَوَّجَنِي ‏ ‏مَوْلَايَ ‏ ‏جَارِيَةً ‏ ‏رُومِيَّةً ‏ ‏فَوَقَعْتُ ‏ ‏عَلَيْهَا فَوَلَدَتْ لِي غُلَامًا أَسْوَدَ مِثْلِي فَسَمَّيْتُهُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏ثُمَّ ‏ ‏وَقَعْتُ ‏ ‏عَلَيْهَا فَوَلَدَتْ لِي غُلَامًا أَسْوَدَ مِثْلِي فَسَمَّيْتُهُ ‏ ‏عُبَيْدَ اللَّهِ ‏ ‏ثُمَّ ‏ ‏طَبِنَ ‏ ‏لِي غُلَامٌ رُومِيٌّ ‏ ‏قَالَ حَسِبْتُهُ قَالَ لِأَهْلِي رُومِيٌّ ‏ ‏يُقَالُ لَهُ ‏ ‏يُوحَنَّسُ ‏ ‏فَرَاطَنَهَا ‏ ‏بِلِسَانِهِ ‏ ‏يَعْنِي بِالرُّومِيَّةِ ‏ ‏فَوَقَعَ ‏ ‏عَلَيْهَا فَوَلَدَتْ لَهُ غُلَامًا أَحْمَرَ كَأَنَّهُ ‏ ‏وَزَغَةٌ ‏ ‏مِنْ ‏ ‏الْوَزَغَاتِ ‏ ‏فَقُلْتُ لَهَا مَا هَذَا فَقَالَتْ هَذَا مِنْ ‏ ‏يُوحَنَّسَ ‏ ‏قَالَ فَارْتَفَعْنَا إِلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَأَقَرَّا جَمِيعًا فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏إِنْ شِئْتُمْ قَضَيْتُ بَيْنَكُمْ بِقَضِيَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏أَنَّ ‏ ‏الْوَلَدَ ‏ ‏لِلْفِرَاشِ ‏ ‏قَالَ حَسِبْتُهُ قَالَ وَجَلَدَهُمَا ‏","","",""],[472,472,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللَّهُ فَالصَّلَوَاتُ ‏ ‏الْمَكْتُوبَاتُ ‏ ‏كَفَّارَاتٌ لِمَا بَيْنَهُنَّ ‏","","",""],[473,473,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَّادَ بْنَ زَاهِرٍ أَبَا رُوَاعٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْطُبُ فَقَالَ إِنَّا وَاللَّهِ قَدْ صَحِبْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السَّفَرِ وَالْحَضَرِ وَكَانَ ‏ ‏يَعُودُ ‏ ‏مَرْضَانَا وَيَتْبَعُ ‏ ‏جَنَائِزَنَا ‏ ‏وَيَغْزُو مَعَنَا ‏ ‏وَيُوَاسِينَا بِالْقَلِيلِ وَالْكَثِيرِ وَإِنَّ نَاسًا يُعْلِمُونِي بِهِ عَسَى أَنْ لَا يَكُونَ أَحَدُهُمْ رَآهُ قَطُّ ‏","","",""],[474,474,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنِي ‏ ‏شُعَيْبٌ أَبُو شَيْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً الْخُرَاسَانِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏قَاعِدًا فِي الْمَقَاعِدِ ‏ ‏فَدَعَا بِطَعَامٍ مِمَّا مَسَّتْهُ النَّارُ فَأَكَلَهُ ثُمَّ قَامَ إِلَى الصَّلَاةِ فَصَلَّى ثُمَّ قَالَ ‏ ‏عُثْمَانُ ‏ ‏قَعَدْتُ مَقْعَدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَكَلْتُ طَعَامَ رَسُولِ اللَّهِ وَصَلَّيْتُ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[475,475,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَرَادَ أَنْ يَبْنِيَ ‏ ‏مَسْجِدَ الْمَدِينَةِ ‏ ‏فَكَرِهَ النَّاسُ ذَاكَ وَأَحَبُّوا أَنْ يَدَعُوهُ عَلَى هَيْئَتِهِ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ مِثْلَهُ ‏","","",""],[476,476,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْكَبِيرِ بْنُ عَبْدِ الْمَجِيدِ أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَعَمَّدَ عَلَيَّ كَذِبًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏بَيْتًا فِي النَّارِ ‏","","",""],[477,477,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ فَرُّوخَ ‏ ‏مَوْلَى ‏ ‏الْقُرَشِيِّينَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْخَلَ اللَّهُ رَجُلًا الْجَنَّةَ كَانَ سَهْلًا مُشْتَرِيًا وَبَائِعًا وَقَاضِيًا ‏ ‏وَمُقْتَضِيًا ‏","","",""],[478,478,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عُثْمَانَ ‏ ‏وَهُوَ مَحْصُورٌ فِي الدَّارِ قَالَ وَلِمَ تَقْتُلُونَنِي ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ رَجُلٌ كَفَرَ بَعْدَ إِسْلَامِهِ أَوْ زَنَى بَعْدَ إِحْصَانِهِ أَوْ قَتَلَ نَفْسًا فَيُقْتَلُ بِهَا ‏","","",""],[479,479,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالِدِ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يُصَلِّيَانِ يَوْمَ الْفِطْرِ وَالْأَضْحَى ثُمَّ يَنْصَرِفَانِ يُذَكِّرَانِ النَّاسَ قَالَ وَسَمِعْتُهُمَا يَقُولَانِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صِيَامِ هَذَيْنِ الْيَوْمَيْنِ ‏","","",""],[480,480,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبْقَى مِنْ نُسُكِكُمْ عِنْدَكُمْ شَيْءٌ بَعْدَ ثَلَاثٍ ‏","","",""],[481,481,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ جَاوَانَ ‏ ‏قَالَ قَالَ ‏ ‏الْأَحْنَفُ ‏ ‏انْطَلَقْنَا حُجَّاجًا فَمَرَرْنَا ‏ ‏بِالْمَدِينَةِ ‏ ‏فَبَيْنَمَا نَحْنُ فِي مَنْزِلِنَا إِذْ جَاءَنَا آتٍ فَقَالَ النَّاسُ مِنْ فَزَعٍ فِي الْمَسْجِدِ فَانْطَلَقْتُ أَنَا وَصَاحِبِي فَإِذَا النَّاسُ مُجْتَمِعُونَ عَلَى نَفَرٍ فِي الْمَسْجِدِ قَالَ فَتَخَلَّلْتُهُمْ حَتَّى قُمْتُ عَلَيْهِمْ فَإِذَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَالزُّبَيْرُ ‏ ‏وَطَلْحَةُ ‏ ‏وَسَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏قَالَ فَلَمْ يَكُنْ ذَلِكَ بِأَسْرَعَ مِنْ أَنْ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏يَمْشِي فَقَالَ أَهَاهُنَا ‏ ‏عَلِيٌّ ‏ ‏قَالُوا نَعَمْ قَالَ أَهَاهُنَا ‏ ‏الزُّبَيْرُ ‏ ‏قَالُوا نَعَمْ قَالَ أَهَاهُنَا ‏ ‏طَلْحَةُ ‏ ‏قَالُوا نَعَمْ قَالَ أَهَاهُنَا ‏ ‏سَعْدٌ ‏ ‏قَالُوا نَعَمْ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يَبْتَاعُ ‏ ‏مِرْبَدَ ‏ ‏بَنِي فُلَانٍ غَفَرَ اللَّهُ لَهُ ‏ ‏فَابْتَعْتُهُ ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي قَدْ ‏ ‏ابْتَعْتُهُ ‏ ‏فَقَالَ اجْعَلْهُ فِي ‏ ‏مَسْجِدِنَا ‏ ‏وَأَجْرُهُ لَكَ قَالُوا نَعَمْ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ يَبْتَاعُ ‏ ‏بِئْرَ رُومَةَ ‏ ‏فَابْتَعْتُهَا ‏ ‏بِكَذَا وَكَذَا فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي قَدْ ‏ ‏ابْتَعْتُهَا ‏ ‏يَعْنِي ‏ ‏بِئْرَ رُومَةَ ‏ ‏فَقَالَ اجْعَلْهَا سِقَايَةً لِلْمُسْلِمِينَ وَأَجْرُهَا لَكَ قَالُوا نَعَمْ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَظَرَ فِي وُجُوهِ الْقَوْمِ يَوْمَ جَيْشِ الْعُسْرَةِ فَقَالَ مَنْ يُجَهِّزُ هَؤُلَاءِ غَفَرَ اللَّهُ لَهُ فَجَهَّزْتُهُمْ حَتَّى مَا يَفْقِدُونَ ‏ ‏خِطَامًا ‏ ‏وَلَا عِقَالًا قَالُوا اللَّهُمَّ نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ اللَّهُمَّ اشْهَدْ اللَّهُمَّ اشْهَدْ ثُمَّ انْصَرَفَ ‏","","",""],[482,482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَيْهِ ‏ ‏عَنْ ‏ ‏بَعْضِ ‏ ‏بَنِي يَعْلَى بْنِ أُمَيَّةَ ‏ ‏قَالَ قَالَ ‏ ‏يَعْلَى ‏ ‏طُفْتُ مَعَ ‏ ‏عُثْمَانَ ‏ ‏فَاسْتَلَمْنَا الرُّكْنَ ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏فَكُنْتُ مِمَّا ‏ ‏يَلِي ‏ ‏الْبَيْتَ ‏ ‏فَلَمَّا بَلَغْنَا الرُّكْنَ ‏ ‏الْغَرْبِيَّ الَّذِي ‏ ‏يَلِي ‏ ‏الْأَسْوَدَ جَرَرْتُ بِيَدِهِ لِيَسْتَلِمَ فَقَالَ مَا شَأْنُكَ فَقُلْتُ أَلَا تَسْتَلِمُ قَالَ فَقَالَ أَلَمْ تَطُفْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ بَلَى قَالَ أَرَأَيْتَهُ ‏ ‏يَسْتَلِمُ ‏ ‏هَذَيْنِ الرُّكْنَيْنِ الْغَرْبِيَّيْنِ قُلْتُ لَا قَالَ أَفَلَيْسَ لَكَ فِيهِ أُسْوَةٌ حَسَنَةٌ قُلْتُ بَلَى قَالَ فَانْفُذْ عَنْكَ ‏","","",""],[483,483,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْحَارِثَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏يَقُولُ ‏ ‏جَلَسَ ‏ ‏عُثْمَانُ ‏ ‏يَوْمًا وَجَلَسْنَا مَعَهُ فَجَاءَهُ الْمُؤَذِّنُ فَدَعَا بِمَاءٍ فِي إِنَاءٍ أَظُنُّهُ سَيَكُونُ فِيهِ ‏ ‏مُدٌّ ‏ ‏فَتَوَضَّأَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ وُضُوئِي هَذَا ثُمَّ قَالَ ‏ ‏وَمَنْ تَوَضَّأَ وُضُوئِي ثُمَّ قَامَ فَصَلَّى صَلَاةَ الظُّهْرِ غُفِرَ لَهُ مَا كَانَ بَيْنَهَا وَبَيْنَ الصُّبْحِ ثُمَّ صَلَّى الْعَصْرَ غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الظُّهْرِ ثُمَّ صَلَّى الْمَغْرِبَ غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الْعَصْرِ ثُمَّ صَلَّى الْعِشَاءَ غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الْمَغْرِبِ ثُمَّ لَعَلَّهُ أَنْ يَبِيتَ يَتَمَرَّغُ لَيْلَتَهُ ثُمَّ إِنْ قَامَ فَتَوَضَّأَ وَصَلَّى الصُّبْحَ غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الْعِشَاءِ وَهُنَّ الْحَسَنَاتُ ‏ ‏يُذْهِبْنَ ‏ ‏السَّيِّئَاتِ ‏ ‏قَالُوا هَذِهِ الْحَسَنَاتُ فَمَا الْبَاقِيَاتُ يَا ‏ ‏عُثْمَانُ ‏ ‏قَالَ ‏ ‏هُنَّ لَا إِلَهَ إِلَّا اللَّهُ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ وَلَا ‏ ‏حَوْلَ ‏ ‏وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[484,484,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْعَاصِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعُثْمَانَ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْتَأْذَنَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُضْطَجِعٌ عَلَى فِرَاشِهِ لَابِسٌ ‏ ‏مِرْطَ ‏ ‏عَائِشَةَ ‏ ‏فَأَذِنَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ كَذَلِكَ فَقَضَى إِلَيْهِ حَاجَتَهُ ثُمَّ انْصَرَفَ ثُمَّ اسْتَأْذَنَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَذِنَ لَهُ وَهُوَ عَلَى تِلْكَ الْحَالِ فَقَضَى إِلَيْهِ حَاجَتَهُ ثُمَّ انْصَرَفَ قَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ثُمَّ اسْتَأْذَنْتُ عَلَيْهِ فَجَلَسَ وَقَالَ ‏ ‏لِعَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏اجْمَعِي عَلَيْكِ ثِيَابَكِ فَقَضَى إِلَيَّ حَاجَتِي ثُمَّ انْصَرَفْتُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏يَا رَسُولَ اللَّهِ مَا لِي لَمْ أَرَكَ ‏ ‏فَزِعْتَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏كَمَا ‏ ‏فَزِعْتَ ‏ ‏لِعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ وَإِنِّي خَشِيتُ إِنْ أَذِنْتُ لَهُ عَلَى تِلْكَ الْحَالِ أَنْ لَا يَبْلُغَ إِلَيَّ فِي حَاجَتِهِ ‏ ‏و قَالَ ‏ ‏اللَّيْثُ ‏ ‏وَقَالَ ‏ ‏جَمَاعَةُ النَّاسِ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَلَا ‏ ‏أَسْتَحْيِي مِمَّنْ ‏ ‏يَسْتَحْيِي مِنْهُ الْمَلَائِكَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ سَعِيدِ بْنِ الْعَاصِ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْعَاصِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُثْمَانَ ‏ ‏وَعَائِشَةَ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْتَأْذَنَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُضْطَجِعٌ عَلَى فِرَاشِهِ لَابِسٌ ‏ ‏مِرْطَ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏عُقَيْلٍ ‏","","",""],[485,485,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي سَلَمَةَ ‏ ‏وَنَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ الرَّحْمَنِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَأَسْبَغَ ‏ ‏الْوُضُوءَ ثُمَّ مَشَى إِلَى صَلَاةٍ مَكْتُوبَةٍ فَصَلَّاهَا غُفِرَ لَهُ ذَنْبُهُ ‏","","",""],[486,486,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ بْنِ مَوْهَبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمِّي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنُ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏رَاحَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏حَاجًّا وَدَخَلَتْ عَلَى ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ أَبِي طَالِبٍ ‏ ‏امْرَأَتُهُ فَبَاتَ مَعَهَا حَتَّى أَصْبَحَ ثُمَّ غَدَا عَلَيْهِ رَدْعُ الطِّيبِ ‏ ‏وَمِلْحَفَةٌ ‏ ‏مُعَصْفَرَةٌ ‏ ‏مُفْدَمَةٌ فَأَدْرَكَ النَّاسَ بِمَلَلٍ قَبْلَ أَنْ يَرُوحُوا فَلَمَّا رَآهُ ‏ ‏عُثْمَانُ ‏ ‏انْتَهَرَ وَأَفَّفَ وَقَالَ أَتَلْبَسُ ‏ ‏الْمُعَصْفَرَ ‏ ‏وَقَدْ نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَنْهَهُ وَلَا إِيَّاكَ إِنَّمَا نَهَانِي ‏","","",""],[487,487,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَأَبُو خَيْثَمَةَ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏وَقَالَ ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنِي عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏صَالِحُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي فَرْوَةَ ‏ ‏أَنَّ ‏ ‏عَامِرَ بْنَ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَانَ بْنَ عُثْمَانَ ‏ ‏يَقُولُ قَالَ ‏ ‏عُثْمَانُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَرَأَيْتَ لَوْ كَانَ ‏ ‏بِفِنَاءِ ‏ ‏أَحَدِكُمْ نَهَرٌ يَجْرِي يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ مَا كَانَ يَبْقَى مِنْ ‏ ‏دَرَنِهِ ‏ ‏قَالُوا لَا شَيْءَ قَالَ إِنَّ الصَّلَوَاتِ تُذْهِبُ الذُّنُوبَ كَمَا يُذْهِبُ الْمَاءُ ‏ ‏الدَّرَنَ ‏","","",""],[488,488,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏مُخَارِقِ بْنِ عَبْدِ اللَّهِ بْنِ جَابِرٍ الْأَحْمَسِيِّ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَشَّ ‏ ‏الْعَرَبَ ‏ ‏لَمْ يَدْخُلْ فِي شَفَاعَتِي وَلَمْ تَنَلْهُ مَوَدَّتِي ‏","","",""],[489,489,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبَّاسُ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو يَحْيَى الْبَزَّازُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ نُصَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْعَوَّامِ بْنِ مُرَاجِمٍ ‏ ‏مِنْ ‏ ‏بَنِي قَيْسِ بْنِ ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْجَمَّاءَ ‏ ‏لَتُقَصُّ مِنْ ‏ ‏الْقَرْنَاءِ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[490,490,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عُثْمَانَ ‏ ‏يَأْمُرُ فِي خُطْبَتِهِ بِقَتْلِ الْكِلَابِ وَذَبْحِ الْحَمَامِ ‏","","",""],[491,491,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏أُمِّ مُوسَى ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏مِنْ أَجْمَلِ النَّاسِ ‏","","",""],[492,492,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ أُصَلِّي فَمَرَّ رَجُلٌ بَيْنَ يَدَيَّ فَمَنَعْتُهُ فَأَبَى فَسَأَلْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏فَقَالَ ‏ ‏لَا يَضُرُّكَ يَا ابْنَ أَخِي ‏","","",""],[493,493,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدٌ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَ ‏ ‏عُثْمَانُ ‏ ‏إِنْ وَجَدْتُمْ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ أَنْ تَضَعُوا رِجْلِي فِي الْقَيْدِ فَضَعُوهَا ‏","","",""],[494,494,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ الْمَخْزُومِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي عَبْدُ الرَّحْمَنِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ ‏ ‏بِعَرَفَةَ ‏ ‏وَهُوَ مُرْدِفٌ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَقَالَ ‏ ‏هَذَا الْمَوْقِفُ وَكُلُّ ‏ ‏عَرَفَةَ ‏ ‏مَوْقِفٌ ثُمَّ دَفَعَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏وَجَعَلَ النَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا وَهُوَ يَلْتَفِتُ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ حَتَّى جَاءَ ‏ ‏الْمُزْدَلِفَةَ ‏ ‏وَجَمَعَ بَيْنَ الصَّلَاتَيْنِ ثُمَّ وَقَفَ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏فَوَقَفَ عَلَى ‏ ‏قُزَحَ ‏ ‏وَأَرْدَفَ ‏ ‏الْفَضْلَ بْنَ الْعَبَّاسِ ‏ ‏وَقَالَ هَذَا الْمَوْقِفُ وَكُلُّ ‏ ‏مُزْدَلِفَةَ ‏ ‏مَوْقِفٌ ثُمَّ دَفَعَ وَجَعَلَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏وَالنَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا وَهُوَ يَلْتَفِتُ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏السَّكِينَةَ ‏ ‏وَذَكَرَ الْحَدِيثَ بِطُولِهِ ‏","","",""],[495,495,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي الْيَعْفُورِ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏أَعْتَقَ عِشْرِينَ مَمْلُوكًا وَدَعَا بِسَرَاوِيلَ فَشَدَّهَا عَلَيْهِ وَلَمْ يَلْبَسْهَا فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ وَقَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَارِحَةَ فِي الْمَنَامِ وَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏وَإِنَّهُمْ قَالُوا لِي ‏ ‏اصْبِرْ فَإِنَّكَ تُفْطِرُ عِنْدَنَا ‏ ‏الْقَابِلَةَ ‏ ‏ثُمَّ دَعَا بِمُصْحَفٍ فَنَشَرَهُ بَيْنَ يَدَيْهِ فَقُتِلَ وَهُوَ بَيْنَ يَدَيْهِ ‏","","",""],[496,496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏وَأَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ غَسْلًا ‏","","",""],[497,497,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ الْمُسَيَّبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي مَوْدُودٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ ثَلَاثَ مَرَّاتٍ لَمْ تَفْجَأْهُ فَاجِئَةُ ‏ ‏بَلَاءٍ ‏ ‏حَتَّى اللَّيْلِ وَمَنْ قَالَهَا حِينَ يُمْسِي لَمْ تَفْجَأْهُ فَاجِئَةُ ‏ ‏بَلَاءٍ ‏ ‏حَتَّى يُصْبِحَ إِنْ شَاءَ اللَّهُ ‏","","",""],[498,498,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عِمْرَانَ بْنِ مَنَّاحٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏أَنَّهُ ‏ ‏رَأَى جَنَازَةً مُقْبِلَةً فَلَمَّا رَآهَا ‏ ‏قَامَ فَقَالَ رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏يَفْعَلُ ذَلِكَ وَخَبَّرَنِي أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[499,499,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِبْرَاهِيمَ التَّرْجُمَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي فَرْوَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَةُ ‏ ‏تَمْنَعُ الرِّزْقَ ‏","","",""],[500,500,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ مُحْرِزٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ فَرُّوخَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏دُفِنَ فِي ثِيَابِهِ بِدِمَائِهِ وَلَمْ يُغَسَّلْ ‏","","",""],[501,501,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو يَحْيَى الْبَزَّازُ مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ بِشْرِ بْنِ سَلْمٍ الْكُوفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْعَبَّاسُ بْنُ الْفَضْلِ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زِيَادٍ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مِحْجَنٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَظَلَّ اللَّهُ عَبْدًا فِي ‏ ‏ظِلِّهِ ‏ ‏يَوْمَ لَا ظِلَّ إِلَّا ‏ ‏ظِلُّهُ ‏ ‏أَنْظَرَ مُعْسِرًا أَوْ تَرَكَ ‏ ‏لِغَارِمٍ ‏","","",""],[502,502,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عُثْمَانَ يَعْنِي الْحَرْبِيَّ أَبُو زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَدْ سَمَّاهُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَةُ ‏ ‏تَمْنَعُ الرِّزْقَ ‏","","",""],[503,503,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُحْرِمُ ‏ ‏لَا يَنْكِحُ وَلَا يُنْكِحُ وَلَا يَخْطُبُ ‏","","",""],[504,504,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏حَدَّثَنِي ‏ ‏نُبَيْهُ بْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي ‏ ‏عُمَرُ بْنُ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏وَكَانَ يَخْطُبُ ‏ ‏بِنْتَ شَيْبَةَ بْنِ عُثْمَانَ ‏ ‏عَلَى ابْنِهِ فَأَرْسَلَ إِلَى ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏وَهُوَ عَلَى الْمَوْسِمِ فَقَالَ أَلَا أُرَاهُ أَعْرَابِيًّا ‏ ‏إِنَّ الْمُحْرِمَ لَا يَنْكِحُ وَلَا يُنْكِحُ ‏ ‏أَخْبَرَنِي ‏ ‏بِذَلِكَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏نُبَيْهٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏بِنَحْوِهِ ‏","","",""],[505,505,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ هِلَالٍ ابْنَةِ وَكِيعٍ ‏ ‏عَنْ ‏ ‏نَائِلَةَ بِنْتِ الْفَرَافِصَةِ ‏ ‏امْرَأَةِ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَتْ ‏ ‏نَعَسَ أَمِيرُ الْمُؤْمِنِينَ ‏ ‏عُثْمَانُ ‏ ‏فَأَغْفَى فَاسْتَيْقَظَ فَقَالَ لَيَقْتُلَنَّنِي الْقَوْمُ قُلْتُ كَلَّا إِنْ شَاءَ اللَّهُ لَمْ يَبْلُغْ ذَاكَ إِنَّ رَعِيَّتَكَ اسْتَعْتَبُوكَ قَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَنَامِي ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالُوا ‏ ‏تُفْطِرُ عِنْدَنَا اللَّيْلَةَ ‏","","",""],[506,506,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ زَعَمَ ‏ ‏أَبُو الْمِقْدَامِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ أَبِي الْحَسَنِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ فَإِذَا أَنَا ‏ ‏بِعُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مُتَّكِئٌ عَلَى رِدَائِهِ ‏ ‏فَأَتَاهُ سَقَّاءَانِ يَخْتَصِمَانِ إِلَيْهِ فَقَضَى بَيْنَهُمَا ثُمَّ أَتَيْتُهُ فَنَظَرْتُ إِلَيْهِ فَإِذَا رَجُلٌ حَسَنُ الْوَجْهِ ‏ ‏بِوَجْنَتِهِ ‏ ‏نَكَتَاتُ ‏ ‏جُدَرِيٍّ ‏ ‏وَإِذَا شَعْرُهُ قَدْ كَسَا ذِرَاعَيْهِ ‏","","",""],[507,507,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَتْنِي ‏ ‏أُمُّ غُرَابٍ ‏ ‏عَنْ ‏ ‏بُنَانَةَ ‏ ‏قَالَتْ ‏ ‏مَا خَضَبَ ‏ ‏عُثْمَانُ ‏ ‏قَطُّ ‏","","",""],[508,508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْقَاسِمِ بْنُ أَبِي الزِّنَادِ ‏ ‏حَدَّثَنِي ‏ ‏وَاقِدُ بْنُ عَبْدِ اللَّهِ التَّمِيمِيُّ ‏ ‏عَنْ ‏ ‏مَنْ ‏ ‏رَأَى ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏ضَبَّبَ أَسْنَانَهُ بِذَهَبٍ ‏","","",""],[509,509,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بُشَيْرٍ ‏ ‏إِمْلَاءً ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ قَيْسٍ الْأَسَدِيُّ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ وَالْمُؤَذِّنُ يُقِيمُ الصَّلَاةَ وَهُوَ ‏ ‏يَسْتَخْبِرُ النَّاسَ يَسْأَلُهُمْ عَنْ أَخْبَارِهِمْ وَأَسْعَارِهِمْ ‏","","",""],[510,510,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَجَدَ فِي ‏ ‏ص ‏","","",""],[511,511,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ مُحْرِزٍ ‏ ‏بَيَّاعُ الْقَوَارِيرِ كُوفِيٌّ ثِقَةٌ كَذَا قَالَ ‏ ‏سُرَيْجٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ فَرُّوخَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الْعِيدَ ‏ ‏فَكَبَّرَ سَبْعًا وَخَمْسًا ‏","","",""],[512,512,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ أَبُو جُمَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏وَذَكَرَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَشِدَّةَ حَيَائِهِ فَقَالَ إِنْ كَانَ لَيَكُونُ فِي الْبَيْتِ وَالْبَابُ عَلَيْهِ مُغْلَقٌ فَمَا يَضَعُ عَنْهُ الثَّوْبَ لِيُفِيضَ عَلَيْهِ الْمَاءَ يَمْنَعُهُ الْحَيَاءُ أَنْ يُقِيمَ ‏ ‏صُلْبَهُ ‏","","",""],[513,513,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ الصَّنْعَانِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أُمَيَّةُ بْنُ شِبْلٍ ‏ ‏وَغَيْرُهُ ‏ ‏قَالُوا ‏ ‏وَلِيَ ‏ ‏عُثْمَانُ ‏ ‏ثِنْتَيْ عَشْرَةَ وَكَانَتْ الْفِتْنَةُ خَمْسَ سِنِينَ ‏","","",""],[514,514,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى بْنِ الطَّبَّاعِ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏قَالَ ‏ ‏وَقُتِلَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَوْمَ الْجُمُعَةِ لِثَمَانِ عَشْرَةَ مَضَتْ مِنْ ذِي الْحِجَّةِ سَنَةَ خَمْسٍ وَثَلَاثِينَ وَكَانَتْ خِلَافَتُهُ ثِنْتَيْ عَشْرَةَ سَنَةً إِلَّا اثْنَيْ عَشَرَ يَوْمًا ‏","","",""],[515,515,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قُتِلَ فِي أَوْسَطِ ‏ ‏أَيَّامِ التَّشْرِيقِ ‏","","",""],[516,516,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏قُتِلَ وَهُوَ ابْنُ تِسْعِينَ سَنَةً ‏ ‏أَوْ ثَمَانٍ وَثَمَانِينَ ‏","","",""],[517,517,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ مُحَمَّدِ بْنِ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَلْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏قَالَ ‏ ‏كُنَّا بِبَابِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي عَشْرِ الْأَضْحَى ‏","","",""],[518,518,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏الزُّبَيْرُ ‏ ‏عَلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَدَفَنَهُ وَكَانَ أَوْصَى إِلَيْهِ ‏","","",""],[519,519,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ ‏ ‏قُتِلَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَنَةَ خَمْسٍ وَثَلَاثِينَ فَكَانَتْ الْفِتْنَةُ خَمْسَ سِنِينَ مِنْهَا أَرْبَعَةُ أَشْهُرٍ ‏ ‏لِلْحَسَنِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[520,520,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَلْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏قَالَ ‏ ‏كُنَّا بِبَابِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي عَشْرِ الْأَضْحَى ‏","","",""],[521,521,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ الْحَكَمِ بْنِ أَوْسٍ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُبَادَةَ الزُّرَقِيُّ الْأَنْصَارِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَوْمَ حُوصِرَ فِي مَوْضِعِ الْجَنَائِزِ وَلَوْ أُلْقِيَ حَجَرٌ لَمْ يَقَعْ إِلَّا عَلَى رَأْسِ رَجُلٍ فَرَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَشْرَفَ ‏ ‏مِنْ الْخَوْخَةِ الَّتِي تَلِي مَقَامَ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ أَيُّهَا النَّاسُ أَفِيكُمْ ‏ ‏طَلْحَةُ ‏ ‏فَسَكَتُوا ثُمَّ قَالَ أَيُّهَا النَّاسُ أَفِيكُمْ ‏ ‏طَلْحَةُ ‏ ‏فَسَكَتُوا ثُمَّ قَالَ يَا أَيُّهَا النَّاسُ أَفِيكُمْ ‏ ‏طَلْحَةُ ‏ ‏فَقَامَ ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَا أَرَاكَ هَاهُنَا مَا كُنْتُ أَرَى أَنَّكَ تَكُونُ فِي جَمَاعَةٍ تَسْمَعُ نِدَائِي آخِرَ ثَلَاثِ مَرَّاتٍ ثُمَّ لَا تُجِيبُنِي ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ يَا ‏ ‏طَلْحَةُ ‏ ‏تَذْكُرُ يَوْمَ كُنْتُ أَنَا وَأَنْتَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَوْضِعِ كَذَا وَكَذَا لَيْسَ مَعَهُ أَحَدٌ مِنْ أَصْحَابِهِ غَيْرِي وَغَيْرُكَ قَالَ نَعَمْ فَقَالَ لَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏طَلْحَةُ ‏ ‏إِنَّهُ لَيْسَ مِنْ نَبِيٍّ إِلَّا وَمَعَهُ مِنْ أَصْحَابِهِ رَفِيقٌ مِنْ أُمَّتِهِ مَعَهُ فِي الْجَنَّةِ وَإِنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏هَذَا ‏ ‏يَعْنِينِي رَفِيقِي مَعِي فِي الْجَنَّةِ ‏ ‏قَالَ ‏ ‏طَلْحَةُ ‏ ‏اللَّهُمَّ نَعَمْ ثُمَّ انْصَرَفَ ‏","","",""],[522,522,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏الْعَبَّاسُ بْنُ الْوَلِيدِ النَّرْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ يَوْمًا فَمَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ ثَلَاثًا ‏ ‏وَحَدَّثَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏ابْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏","","",""],[523,523,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏وَهْبُ بْنُ بَقِيَّةَ الْوَاسِطِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ قَبِيصَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ قَائِمًا عِنْدَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ أَلَا أُنَبِّئُكُمْ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قُلْنَا بَلَى ‏ ‏فَدَعَا بِمَاءٍ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ إِلَى مِرْفَقَيْهِ ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثُمَّ قَالَ هَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏","","",""],[524,524,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرِ بْنِ عَلِيٍّ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِىُّ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالُ بْنُ حِقٍّ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ حَزْنٍ الْقُشَيْرِيِّ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الدَّارَ يَوْمَ أُصِيبَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَاطَّلَعَ عَلَيْهِمْ اطِّلَاعَةً فَقَالَ ادْعُوا لِي ‏ ‏صَاحِبَيْكُمْ اللَّذَيْنِ ‏ ‏أَلَّبَاكُمْ ‏ ‏عَلَيَّ فَدُعِيَا لَهُ فَقَالَ نَشَدْتُكُمَا اللَّهَ أَتَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏ضَاقَ الْمَسْجِدُ بِأَهْلِهِ فَقَالَ ‏ ‏مَنْ يَشْتَرِي هَذِهِ الْبُقْعَةَ مِنْ خَالِصِ مَالِهِ فَيَكُونَ فِيهَا كَالْمُسْلِمِينَ وَلَهُ خَيْرٌ مِنْهَا فِي الْجَنَّةِ فَاشْتَرَيْتُهَا مِنْ خَالِصِ مَالِي فَجَعَلْتُهَا بَيْنَ الْمُسْلِمِينَ وَأَنْتُمْ تَمْنَعُونِي أَنْ أُصَلِّيَ فِيهِ رَكْعَتَيْنِ ثُمَّ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏لَمْ يَكُنْ فِيهَا بِئْرٌ ‏ ‏يُسْتَعْذَبُ ‏ ‏مِنْهُ إِلَّا ‏ ‏رُومَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يَشْتَرِيهَا مِنْ خَالِصِ مَالِهِ فَيَكُونَ دَلْوُهُ فِيهَا كَدُلِيِّ الْمُسْلِمِينَ وَلَهُ خَيْرٌ مِنْهَا فِي الْجَنَّةِ فَاشْتَرَيْتُهَا مِنْ خَالِصِ مَالِي فَأَنْتُمْ تَمْنَعُونِي أَنْ أَشْرَبَ مِنْهَا ثُمَّ قَالَ هَلْ تَعْلَمُونَ أَنِّي صَاحِبُ جَيْشِ الْعُسْرَةِ قَالُوا اللَّهُمَّ نَعَمْ ‏","","",""],[525,525,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَأَبُو خَيْثَمَةَ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏الْوَلِيدَ بْنَ عُقْبَةَ ‏ ‏فَقَالَ لَهُ ‏ ‏الْوَلِيدُ ‏ ‏مَا لِي أَرَاكَ قَدْ جَفَوْتَ أَمِيرَ الْمُؤْمِنِينَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَبْلِغْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَأَمَّا قَوْلُهُ إِنِّي تَخَلَّفْتُ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَإِنِّي كُنْتُ أُمَرِّضُ ‏ ‏رُقَيَّةَ بِنْتَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى مَاتَتْ وَقَدْ ‏ ‏ضَرَبَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَهْمٍ ‏ ‏وَمَنْ ضَرَبَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَهْمٍ ‏ ‏فَقَدْ شَهِدَ ‏ ‏فَذَكَرَ الْحَدِيثَ بِطُولِهِ إِلَى آخِرِهِ ‏","","",""],[526,526,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُفْيَانُ بْنُ وَكِيعٍ ‏ ‏حَدَّثَنِي ‏ ‏قَبِيصَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏كَيْفَ ‏ ‏بَايَعْتُمْ ‏ ‏عُثْمَانَ ‏ ‏وَتَرَكْتُمْ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ مَا ذَنْبِي قَدْ بَدَأْتُ ‏ ‏بِعَلِيٍّ ‏ ‏فَقُلْتُ أُبَايِعُكَ عَلَى كِتَابِ اللَّهِ وَسُنَّةِ رَسُولِهِ وَسِيرَةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ فَقَالَ فِيمَا اسْتَطَعْتُ قَالَ ثُمَّ ‏ ‏عَرَضْتُهَا عَلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَبِلَهَا ‏","","",""],[527,527,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهْرَةُ بْنُ مَعْبَدٍ الْقُرَشِيُّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ أَيُّهَا النَّاسُ إِنِّي كَتَمْتُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَرَاهِيَةَ تَفَرُّقِكُمْ عَنِّي ثُمَّ بَدَا لِي أَنْ أُحَدِّثَكُمُوهُ لِيَخْتَارَ امْرُؤٌ لِنَفْسِهِ مَا بَدَا لَهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ مِنْ الْمَنَازِلِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ إِبْرَاهِيمَ بَاهِلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي ذُبَابٍ ‏ ‏وَذَكَرَهُ ‏","","",""],[528,528,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ وَرْدَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ ‏ ‏يَخْطُبُ عَلَى الْمِنْبَرِ وَهُوَ يَقُولُ كُنْتُ أَبْتَاعُ التَّمْرَ مِنْ بَطْنٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏يُقَالُ لَهُمْ ‏ ‏بَنُو قَيْنُقَاعٍ ‏ ‏فَأَبِيعُهُ بِرِبْحِ ‏ ‏الْآصُعِ ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏إِذَا اشْتَرَيْتَ فَاكْتَلْ وَإِذَا بِعْتَ فَكِلْ ‏","","",""],[529,529,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَهُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏إِنَّ اللَّهَ قَدْ بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏بِالْحَقِّ فَكُنْتُ مِمَّنْ اسْتَجَابَ لِلَّهِ وَلِرَسُولِهِ وَآمَنَ بِمَا بَعَثَ بِهِ ‏ ‏مُحَمَّدًا ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏ثُمَّ هَاجَرْتُ الْهِجْرَتَيْنِ وَنِلْتُ ‏ ‏صِهْرَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَاللَّهِ مَا عَصَيْتُهُ وَلَا غَشَشْتُهُ حَتَّى تَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[530,530,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ عَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏فَقَالَ ‏ ‏هَذَا الْمَوْقِفُ ‏ ‏وَعَرَفَةُ ‏ ‏كُلُّهَا مَوْقِفٌ ‏ ‏وَأَفَاضَ ‏ ‏حِينَ غَابَتْ الشَّمْسُ ثُمَّ أَرْدَفَ ‏ ‏أُسَامَةَ ‏ ‏فَجَعَلَ ‏ ‏يُعْنِقُ ‏ ‏عَلَى بَعِيرِهِ وَالنَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا يَلْتَفِتُ إِلَيْهِمْ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ ثُمَّ أَتَى ‏ ‏جَمْعًا ‏ ‏فَصَلَّى بِهِمْ الصَّلَاتَيْنِ الْمَغْرِبَ وَالْعِشَاءَ ثُمَّ بَاتَ حَتَّى أَصْبَحَ ثُمَّ أَتَى ‏ ‏قُزَحَ ‏ ‏فَوَقَفَ عَلَى ‏ ‏قُزَحَ ‏ ‏فَقَالَ هَذَا الْمَوْقِفُ ‏ ‏وَجَمْعٌ ‏ ‏كُلُّهَا مَوْقِفٌ ثُمَّ سَارَ حَتَّى أَتَى ‏ ‏مُحَسِّرًا ‏ ‏فَوَقَفَ عَلَيْهِ ‏ ‏فَقَرَعَ ‏ ‏نَاقَتَهُ ‏ ‏فَخَبَّتْ ‏ ‏حَتَّى ‏ ‏جَازَ ‏ ‏الْوَادِيَ ‏ ‏ثُمَّ حَبَسَهَا ‏ ‏ثُمَّ أَرْدَفَ ‏ ‏الْفَضْلَ ‏ ‏وَسَارَ حَتَّى أَتَى ‏ ‏الْجَمْرَةَ ‏ ‏فَرَمَاهَا ثُمَّ أَتَى ‏ ‏الْمَنْحَرَ ‏ ‏فَقَالَ هَذَا ‏ ‏الْمَنْحَرُ ‏ ‏وَمِنًى ‏ ‏كُلُّهَا مَنْحَرٌ قَالَ وَاسْتَفْتَتْهُ ‏ ‏جَارِيَةٌ ‏ ‏شَابَّةٌ مِنْ ‏ ‏خَثْعَمَ ‏ ‏فَقَالَتْ إِنَّ أَبِي شَيْخٌ كَبِيرٌ قَدْ ‏ ‏أَفْنَدَ ‏ ‏وَقَدْ أَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فِي الْحَجِّ فَهَلْ يُجْزِئُ عَنْهُ أَنْ أُؤَدِّيَ عَنْهُ قَالَ نَعَمْ فَأَدِّي عَنْ أَبِيكِ قَالَ وَقَدْ لَوَى عُنُقَ ‏ ‏الْفَضْلِ ‏ ‏فَقَالَ لَهُ ‏ ‏الْعَبَّاسُ ‏ ‏يَا رَسُولَ اللَّهِ لِمَ لَوَيْتَ عُنُقَ ابْنِ عَمِّكَ قَالَ رَأَيْتُ شَابًّا وَشَابَّةً فَلَمْ آمَنْ الشَّيْطَانَ عَلَيْهِمَا قَالَ ثُمَّ جَاءَهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ حَلَقْتُ قَبْلَ أَنْ أَنْحَرَ قَالَ انْحَرْ وَلَا حَرَجَ ثُمَّ أَتَاهُ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أَفَضْتُ ‏ ‏قَبْلَ أَنْ أَحْلِقَ قَالَ احْلِقْ ‏ ‏أَوْ قَصِّرْ ‏ ‏وَلَا حَرَجَ ثُمَّ أَتَى ‏ ‏الْبَيْتَ ‏ ‏فَطَافَ بِهِ ثُمَّ أَتَى ‏ ‏زَمْزَمَ ‏ ‏فَقَالَ يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏سِقَايَتَكُمْ وَلَوْلَا أَنْ يَغْلِبَكُمْ النَّاسُ عَلَيْهَا ‏ ‏لَنَزَعْتُ ‏ ‏بِهَا ‏","","",""],[531,531,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَرْبِ بْنِ أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَوْلُ الْغُلَامِ ‏ ‏يُنْضَحُ ‏ ‏عَلَيْهِ وَبَوْلُ ‏ ‏الْجَارِيَةِ ‏ ‏يُغْسَلُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏هَذَا مَا لَمْ يَطْعَمَا فَإِذَا طَعِمَا غُسِلَ بَوْلُهُمَا ‏","","",""],[532,532,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ الْمَخْزُومِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيِّ بْنِ حُسَيْنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ ‏ ‏بِعَرَفَةَ ‏ ‏وَهُوَ مُرْدِفٌ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَقَالَ ‏ ‏هَذَا الْمَوْقِفُ وَكُلُّ ‏ ‏عَرَفَةَ ‏ ‏مَوْقِفٌ ثُمَّ دَفَعَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏وَجَعَلَ النَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا وَهُوَ يَلْتَفِتُ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ حَتَّى جَاءَ ‏ ‏الْمُزْدَلِفَةَ ‏ ‏وَجَمَعَ بَيْنَ الصَّلَاتَيْنِ ثُمَّ وَقَفَ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏فَوَقَفَ عَلَى ‏ ‏قُزَحَ ‏ ‏وَأَرْدَفَ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏وَقَالَ هَذَا الْمَوْقِفُ وَكُلُّ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏مَوْقِفٌ ثُمَّ دَفَعَ وَجَعَلَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏وَالنَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا وَهُوَ يَلْتَفِتُ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ حَتَّى جَاءَ ‏ ‏مُحَسِّرًا ‏ ‏فَقَرَعَ ‏ ‏رَاحِلَتَهُ ‏ ‏فَخَبَّتْ حَتَّى خَرَجَ ثُمَّ عَادَ لِسَيْرِهِ الْأَوَّلِ حَتَّى رَمَى الْجَمْرَةَ ثُمَّ جَاءَ ‏ ‏الْمَنْحَرَ ‏ ‏فَقَالَ هَذَا ‏ ‏الْمَنْحَرُ ‏ ‏وَكُلُّ ‏ ‏مِنًى ‏ ‏مَنْحَرٌ ثُمَّ جَاءَتْهُ امْرَأَةٌ شَابَّةٌ مِنْ ‏ ‏خَثْعَمَ ‏ ‏فَقَالَتْ إِنَّ أَبِي شَيْخٌ كَبِيرٌ وَقَدْ ‏ ‏أَفْنَدَ ‏ ‏وَأَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فِي الْحَجِّ وَلَا يَسْتَطِيعُ أَدَاءَهَا فَيُجْزِئُ عَنْهُ أَنْ أُؤَدِّيَهَا عَنْهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ وَجَعَلَ يَصْرِفُ وَجْهَ ‏ ‏الْفَضْلِ بْنِ الْعَبَّاسِ ‏ ‏عَنْهَا ثُمَّ أَتَاهُ رَجُلٌ فَقَالَ إِنِّي رَمَيْتُ الْجَمْرَةَ وَأَفَضْتُ وَلَبِسْتُ وَلَمْ أَحْلِقْ قَالَ فَلَا حَرَجَ فَاحْلِقْ ثُمَّ أَتَاهُ رَجُلٌ آخَرُ فَقَالَ إِنِّي رَمَيْتُ وَحَلَقْتُ وَلَبِسْتُ وَلَمْ أَنْحَرْ فَقَالَ لَا حَرَجَ فَانْحَرْ ثُمَّ أَفَاضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا ‏ ‏بِسَجْلٍ ‏ ‏مِنْ مَاءِ ‏ ‏زَمْزَمَ ‏ ‏فَشَرِبَ مِنْهُ وَتَوَضَّأَ ثُمَّ قَالَ انْزِعُوا يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَلَوْلَا أَنْ تُغْلَبُوا عَلَيْهَا لَنَزَعْتُ قَالَ ‏ ‏الْعَبَّاسُ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي رَأَيْتُكَ تَصْرِفُ وَجْهَ ابْنِ أَخِيكَ قَالَ إِنِّي رَأَيْتُ غُلَامًا شَابًّا ‏ ‏وَجَارِيَةً ‏ ‏شَابَّةً فَخَشِيتُ عَلَيْهِمَا الشَّيْطَانَ ‏","","",""],[533,533,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا عَوَّذَ مَرِيضًا قَالَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا ‏ ‏يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[534,534,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُؤَمِّرًا أَحَدًا دُونَ مَشُورَةِ الْمُؤْمِنِينَ لَأَمَّرْتُ ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏","","",""],[535,535,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سَلَمَةَ بْنِ أَبِي الْحُسَامِ ‏ ‏مَدَنِيٌّ مَوْلًى لِآلِ ‏ ‏عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏بَيْنَمَا نَحْنُ ‏ ‏بِمِنًى ‏ ‏إِذَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذِهِ أَيَّامُ أَكْلٍ وَشُرْبٍ فَلَا يَصُومُهَا أَحَدٌ وَاتَّبَعَ النَّاسَ عَلَى جَمَلِهِ يَصْرُخُ بِذَلِكَ ‏","","",""],[536,536,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَرَفَعَهُ قَالَ ‏ ‏مَنْ كَذَبَ فِي حُلْمِهِ كُلِّفَ عَقْدَ شَعِيرَةٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[537,537,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْ الْفَجْرِ عِنْدَ الْإِقَامَةِ ‏","","",""],[538,538,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ الْعُكْلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏كَانَتْ لِي سَاعَةٌ مِنْ ‏ ‏السَّحَرِ ‏ ‏أَدْخُلُ فِيهَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنْ كَانَ قَائِمًا ‏ ‏يُصَلِّي سَبَّحَ بِي فَكَانَ ذَاكَ إِذْنُهُ لِي وَإِنْ لَمْ يَكُنْ ‏ ‏يُصَلِّي أَذِنَ لِي ‏","","",""],[539,539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُبَيْدِ بْنِ أَبِي كَرِيمَةَ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحِيمِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏يَقُولُ ‏ ‏أَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا نَائِمٌ ‏ ‏وَفَاطِمَةُ ‏ ‏وَذَلِكَ مِنْ ‏ ‏السَّحَرِ ‏ ‏حَتَّى قَامَ عَلَى الْبَابِ فَقَالَ أَلَا تُصَلُّونَ فَقُلْتُ مُجِيبًا لَهُ يَا رَسُولَ اللَّهِ إِنَّمَا نُفُوسُنَا بِيَدِ اللَّهِ فَإِذَا شَاءَ أَنْ يَبْعَثَنَا قَالَ فَرَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَرْجِعْ إِلَى الْكَلَامِ فَسَمِعْتُهُ حِينَ وَلَّى يَقُولُ وَضَرَبَ بِيَدِهِ عَلَى فَخِذِهِ ‏ { ‏وَكَانَ الْإِنْسَانُ أَكْثَرَ شَيْءٍ ‏ ‏جَدَلًا ‏ }","","",""],[540,540,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَهْلُهُ يَغْتَسِلُونَ مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[541,541,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَانْتَهَيْنَا إِلَى قَوْمٍ قَدْ بَنَوْا ‏ ‏زُبْيَةً ‏ ‏لِلْأَسَدِ فَبَيْنَا هُمْ كَذَلِكَ يَتَدَافَعُونَ إِذْ سَقَطَ رَجُلٌ فَتَعَلَّقَ بِآخَرَ ثُمَّ تَعَلَّقَ رَجُلٌ بِآخَرَ حَتَّى صَارُوا فِيهَا أَرْبَعَةً فَجَرَحَهُمْ الْأَسَدُ ‏ ‏فَانْتَدَبَ ‏ ‏لَهُ رَجُلٌ بِحَرْبَةٍ فَقَتَلَهُ وَمَاتُوا مِنْ جِرَاحَتِهِمْ كُلُّهُمْ فَقَامُوا ‏ ‏أَوْلِيَاءُ ‏ ‏الْأَوَّلِ إِلَى ‏ ‏أَوْلِيَاءِ ‏ ‏الْآخِرِ فَأَخْرَجُوا السِّلَاحَ لِيَقْتَتِلُوا فَأَتَاهُمْ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى ‏ ‏تَفِيئَةِ ‏ ‏ذَلِكَ فَقَالَ تُرِيدُونَ أَنْ تَقَاتَلُوا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيٌّ إِنِّي ‏ ‏أَقْضِي ‏ ‏بَيْنَكُمْ ‏ ‏قَضَاءً ‏ ‏إِنْ رَضِيتُمْ فَهُوَ ‏ ‏الْقَضَاءُ ‏ ‏وَإِلَّا حَجَزَ بَعْضُكُمْ عَنْ بَعْضٍ حَتَّى تَأْتُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَكُونَ هُوَ الَّذِي ‏ ‏يَقْضِي ‏ ‏بَيْنَكُمْ فَمَنْ عَدَا بَعْدَ ذَلِكَ فَلَا حَقَّ لَهُ ‏ ‏اجْمَعُوا مِنْ قَبَائِلِ الَّذِينَ حَفَرُوا الْبِئْرَ رُبُعَ ‏ ‏الدِّيَةِ ‏ ‏وَثُلُثَ ‏ ‏الدِّيَةِ ‏ ‏وَنِصْفَ ‏ ‏الدِّيَةِ ‏ ‏وَالدِّيَةَ ‏ ‏كَامِلَةً فَلِلْأَوَّلِ الرُّبُعُ لِأَنَّهُ هَلَكَ مَنْ فَوْقَهُ وَلِلثَّانِي ثُلُثُ ‏ ‏الدِّيَةِ ‏ ‏وَلِلثَّالِثِ نِصْفُ ‏ ‏الدِّيَةِ ‏ ‏فَأَبَوْا أَنْ يَرْضَوْا فَأَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عِنْدَ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَصُّوا عَلَيْهِ الْقِصَّةَ فَقَالَ أَنَا ‏ ‏أَقْضِي بَيْنَكُمْ وَاحْتَبَى فَقَالَ رَجُلٌ مِنْ الْقَوْمِ إِنَّ ‏ ‏عَلِيًّا ‏ ‏قَضَى ‏ ‏فِينَا فَقَصُّوا عَلَيْهِ الْقِصَّةَ ‏ ‏فَأَجَازَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏وَلِلرَّابِعِ ‏ ‏الدِّيَةُ ‏ ‏كَامِلَةً ‏","","",""],[542,542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏كَتَبْتُ إِلَيْكَ بِخَطِّي وَخَتَمْتُ الْكِتَابَ بِخَاتَمِي ‏ ‏يَذْكُرُ أَنَّ ‏ ‏اللَّيْثَ بْنَ سَعْدٍ ‏ ‏حَدَّثَهُمْ عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏أَنَّ ‏ ‏الْحُسَيْنَ بْنَ عَلِيٍّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَرَقَهُ ‏ ‏وَفَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَقَالَ أَلَا تُصَلُّونَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا أَنْفُسُنَا بِيَدِ اللَّهِ فَإِذَا شَاءَ أَنْ يَبْعَثَنَا بَعَثَنَا وَانْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ قُلْتُ لَهُ ذَلِكَ ثُمَّ سَمِعْتُهُ وَهُوَ مُدْبِرٌ يَضْرِبُ فَخِذَهُ وَيَقُولُ ‏ { ‏وَكَانَ الْإِنْسَانُ أَكْثَرَ شَيْءٍ ‏ ‏جَدَلًا ‏ }","","",""],[543,543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْأَزْدِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ جَعْفَرِ بْنِ مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ بْنِ عَلِيٍّ ‏ ‏حَدَّثَنِي ‏ ‏أَخِي ‏ ‏مُوسَى بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ بِيَدِ ‏ ‏حَسَنٍ ‏ ‏وَحُسَيْنٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ ‏ ‏مَنْ أَحَبَّنِي وَأَحَبَّ هَذَيْنِ وَأَبَاهُمَا وَأُمَّهُمَا كَانَ مَعِي فِي دَرَجَتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[544,544,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ السَّبَئِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ الْغَافِقِىِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا ‏","","",""],[545,545,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏يَوْمَ الْأَضْحَى ‏ ‏فَقَرَّبَ إِلَيْنَا ‏ ‏خَزِيرَةً ‏ ‏فَقُلْتُ أَصْلَحَكَ اللَّهُ لَوْ قَرَّبْتَ إِلَيْنَا مِنْ هَذَا الْبَطِّ ‏ ‏يَعْنِي الْوَزَّ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَكْثَرَ الْخَيْرَ فَقَالَ يَا ‏ ‏ابْنَ زُرَيْرٍ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِلْخَلِيفَةِ مِنْ مَالِ اللَّهِ إِلَّا ‏ ‏قَصْعَتَانِ ‏ ‏قَصْعَةٌ ‏ ‏يَأْكُلُهَا هُوَ وَأَهْلُهُ ‏ ‏وَقَصْعَةٌ ‏ ‏يَضَعُهَا بَيْنَ يَدَيْ النَّاسِ ‏","","",""],[546,546,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏أُمِّ مُوسَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مَا رَمِدْتُ مُنْذُ ‏ ‏تَفَلَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عَيْنِي ‏","","",""],[547,547,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ فِي أَوَّلِ اللَّيْلِ وَفِي وَسَطِهِ وَفِي آخِرِهِ ثُمَّ ثَبَتَ لَهُ الْوَتْرُ فِي آخِرِهِ ‏","","",""],[548,548,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِبْرَاهِيمَ التَّرْجُمَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏فَاطِمَةَ بِنْتِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُدِيمُوا النَّظَرَ إِلَى ‏ ‏الْمُجَذَّمِينَ ‏ ‏وَإِذَا كَلَّمْتُمُوهُمْ فَلْيَكُنْ بَيْنَكُمْ وَبَيْنَهُمْ ‏ ‏قِيدُ ‏ ‏رُمْحٍ ‏","","",""],[549,549,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَلِيُّ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ وَإِنْ شَقَّ عَلَيْكَ وَلَا تَأْكُلْ ‏ ‏الصَّدَقَةَ ‏ ‏وَلَا ‏ ‏تُنْزِ ‏ ‏الْحَمِيرَ عَلَى الْخَيْلِ وَلَا تُجَالِسْ أَصْحَابَ ‏ ‏النُّجُومِ ‏","","",""],[550,550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏النَّزَّالِ بْنِ سَبْرَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِكُوزٍ مِنْ مَاءٍ وَهُوَ فِي ‏ ‏الرَّحْبَةِ ‏ ‏فَأَخَذَ كَفًّا مِنْ مَاءٍ فَمَضْمَضَ وَاسْتَنْشَقَ وَمَسَحَ وَجْهَهُ وَذِرَاعَيْهِ وَرَأْسَهُ ثُمَّ شَرِبَ وَهُوَ قَائِمٌ ثُمَّ قَالَ هَذَا وُضُوءُ مَنْ لَمْ يُحْدِثْ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ‏","","",""],[551,551,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[552,552,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ ‏ ‏عَنْ ‏ ‏أُمِّ مُوسَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ آخِرُ كَلَامِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ الصَّلَاةَ اتَّقُوا اللَّهَ فِيمَا مَلَكَتْ أَيْمَانُكُمْ ‏","","",""],[553,553,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَجْعَلَ خَاتَمِي فِي هَذِهِ السَّبَّاحَةِ أَوْ الَّتِي تَلِيهَا ‏","","",""],[554,554,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَنْبَأَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏ثُمَّ شَهِدْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَعْدَ ذَلِكَ يَوْمَ عِيدٍ بَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ وَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُمْسِكَ أَحَدٌ مِنْ نُسُكِهِ شَيْئًا فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏","","",""],[555,555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ هَاشِمٍ يَعْنِي ابْنَ الْبَرِيدِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيَّرَ نِسَاءَهُ الدُّنْيَا وَالْآخِرَةَ وَلَمْ يُخَيِّرْهُنَّ الطَّلَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَاه ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ هَاشِمِ بْنِ الْبَرِيدِ ‏ ‏فَذَكَرَ مِثْلَهُ وَقَالَ خَيَّرَ نِسَاءَهُ بَيْنَ الدُّنْيَا وَالْآخِرَةِ وَلَمْ يُخَيِّرْهُنَّ الطَّلَاقَ ‏","","",""],[556,556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُوسُفَ الْمُؤَدِّبُ يَعْقُوبُ ‏ ‏جَارُنَا ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ الْمُطَّلِبِ ‏ ‏عَنِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ ‏","","",""],[557,557,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ الْأَحْزَابِ ‏ ‏مَلَأَ اللَّهُ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا كَمَا شَغَلُونَا عَنْ الصَّلَاةِ حَتَّى ‏ ‏آبَتْ ‏ ‏الشَّمْسُ ‏","","",""],[558,558,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَعَبْدِ اللَّهِ ‏ ‏ابْنَيْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِمَا ‏ ‏وَكَانَ ‏ ‏حَسَنٌ ‏ ‏أَرْضَاهُمَا فِي أَنْفُسِنَا ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قَالَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ نِكَاحِ ‏ ‏الْمُتْعَةِ ‏ ‏وَعَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ زَمَنَ ‏ ‏خَيْبَرَ ‏","","",""],[559,559,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُقَسِّمَ ‏ ‏بُدْنَهُ ‏ ‏أَقُومُ عَلَيْهَا وَأَنْ أُقَسِّمَ جُلُودَهَا ‏ ‏وَجِلَالَهَا ‏ ‏وَأَمَرَنِي أَنْ لَا أُعْطِيَ الْجَازِرَ مِنْهَا شَيْئًا وَقَالَ نَحْنُ ‏ ‏نُعْطِيهِ مِنْ عِنْدِنَا ‏","","",""],[560,560,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أُثَيْعٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏هَمْدَانَ ‏ ‏سَأَلْنَا ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِأَيِّ شَيْءٍ بُعِثْتَ ‏ ‏يَعْنِي يَوْمَ بَعَثَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي الْحَجَّةِ قَالَ ‏ ‏بُعِثْتُ بِأَرْبَعٍ لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُؤْمِنَةٌ وَلَا يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏عُرْيَانٌ وَمَنْ كَانَ بَيْنَهُ وَبَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهْدٌ ‏ ‏فَعَهْدُهُ إِلَى مُدَّتِهِ وَلَا يَحُجُّ الْمُشْرِكُونَ وَالْمُسْلِمُونَ بَعْدَ عَامِهِمْ هَذَا ‏","","",""],[561,561,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَضَى ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏الدَّيْنَ قَبْلَ الْوَصِيَّةِ وَأَنْتُمْ تَقْرَءُونَ الْوَصِيَّةَ قَبْلَ الدَّيْنِ وَأَنَّ أَعْيَانَ بَنِي الْأُمِّ يَتَوَارَثُونَ دُونَ بَنِي ‏ ‏الْعَلَّاتِ ‏","","",""],[562,562,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أُعْطِيكُمْ وَأَدَعُ ‏ ‏أَهْلَ الصُّفَّةِ ‏ ‏تَلَوَّى بُطُونُهُمْ مِنْ الْجُوعِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً لَا أُخْدِمُكُمَا وَأَدَعُ ‏ ‏أَهْلَ الصُّفَّةِ ‏ ‏تَطْوَى ‏","","",""],[563,563,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ أَبِي زِيَادٍ الْقَطْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏حَرْبٌ أَبُو سُفْيَانَ الْمِنْقَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ أَبُو جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فِي الْمَسْعَى كَاشِفًا عَنْ ثَوْبِهِ قَدْ بَلَغَ إِلَى رُكْبَتَيْهِ ‏","","",""],[564,564,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كُنْتُ آتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْتَأْذِنُ ‏ ‏فَإِنْ كَانَ فِي صَلَاةٍ سَبَّحَ وَإِنْ كَانَ فِي غَيْرِ صَلَاةٍ أَذِنَ لِي ‏","","",""],[565,565,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏قَالَ ‏ ‏سَأَلْنَا ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏هَلْ عِنْدَكُمْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْءٌ بَعْدَ الْقُرْآنِ قَالَ لَا وَالَّذِي ‏ ‏فَلَقَ ‏ ‏الْحَبَّةَ وَبَرَأَ النَّسَمَةَ إِلَّا فَهْمٌ ‏ ‏يُؤْتِيهِ اللَّهُ عَزَّ وَجَلَّ رَجُلًا فِي الْقُرْآنِ أَوْ مَا فِي الصَّحِيفَةِ قُلْتُ وَمَا فِي الصَّحِيفَةِ قَالَ ‏ ‏الْعَقْلُ ‏ ‏وَفِكَاكُ ‏ ‏الْأَسِيرِ وَلَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ ‏","","",""],[566,566,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَسَنُ بْنُ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي رَافِعٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏إِنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ أَبِي رَافِعٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏وَالزُّبَيْرَ ‏ ‏وَالْمِقْدَادَ ‏ ‏فَقَالَ انْطَلِقُوا حَتَّى تَأْتُوا ‏ ‏رَوْضَةَ خَاخٍ ‏ ‏فَإِنَّ بِهَا ‏ ‏ظَعِينَةً ‏ ‏مَعَهَا ‏ ‏كِتَابٌ ‏ ‏فَخُذُوهُ مِنْهَا فَانْطَلَقْنَا تَعَادَى بِنَا خَيْلُنَا حَتَّى أَتَيْنَا ‏ ‏الرَّوْضَةَ ‏ ‏فَإِذَا نَحْنُ ‏ ‏بِالظَّعِينَةِ ‏ ‏فَقُلْنَا أَخْرِجِي ‏ ‏الْكِتَابَ ‏ ‏قَالَتْ مَا مَعِي مِنْ كِتَابٍ قُلْنَا ‏ ‏لَتُخْرِجِنَّ ‏ ‏الْكِتَابَ ‏ ‏أَوْ لَنَقْلِبَنَّ الثِّيَابَ قَالَ فَأَخْرَجَتْ ‏ ‏الْكِتَابَ ‏ ‏مِنْ ‏ ‏عِقَاصِهَا ‏ ‏فَأَخَذْنَا الْكِتَابَ فَأَتَيْنَا بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا فِيهِ مِنْ ‏ ‏حَاطِبِ بْنِ أَبِي بَلْتَعَةَ ‏ ‏إِلَى نَاسٍ مِنْ الْمُشْرِكِينَ ‏ ‏بِمَكَّةَ ‏ ‏يُخْبِرُهُمْ بِبَعْضِ أَمْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏حَاطِبُ ‏ ‏مَا هَذَا قَالَ لَا تَعْجَلْ عَلَيَّ إِنِّي كُنْتُ امْرَأً ‏ ‏مُلْصَقًا ‏ ‏فِي ‏ ‏قُرَيْشٍ ‏ ‏وَلَمْ أَكُنْ مِنْ أَنْفُسِهَا وَكَانَ مَنْ كَانَ مَعَكَ ‏ ‏مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏لَهُمْ قَرَابَاتٌ يَحْمُونَ أَهْلِيهِمْ ‏ ‏بِمَكَّةَ ‏ ‏فَأَحْبَبْتُ إِذْ فَاتَنِي ذَلِكَ مِنْ النَّسَبِ فِيهِمْ أَنْ أَتَّخِذَ فِيهِمْ ‏ ‏يَدًا ‏ ‏يَحْمُونَ بِهَا قَرَابَتِي وَمَا فَعَلْتُ ذَلِكَ كُفْرًا وَلَا ارْتِدَادًا عَنْ دِينِي وَلَا رِضًا بِالْكُفْرِ بَعْدَ الْإِسْلَامِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ قَدْ صَدَقَكُمْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏دَعْنِي أَضْرِبْ عُنُقَ هَذَا الْمُنَافِقِ فَقَالَ إِنَّهُ قَدْ ‏ ‏شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَمَا يُدْرِيكَ لَعَلَّ اللَّهَ قَدْ اطَّلَعَ عَلَى أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ اعْمَلُوا مَا شِئْتُمْ فَقَدْ غَفَرْتُ لَكُمْ ‏","","",""],[567,567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏حَجَّاجُ بْنُ يُوسُفَ الشَّاعِرُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَالِمٍ أَبِي جَهْضَمٍ ‏ ‏أَنَّ ‏ ‏أَبَا جَعْفَرٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَانِي عَنْ ثَلَاثَةٍ ‏ ‏قَالَ فَمَا أَدْرِي لَهُ خَاصَّةً أَمْ لِلنَّاسِ عَامَّةً ‏ ‏نَهَانِي عَنْ ‏ ‏الْقَسِّيِّ ‏ ‏وَالْمِيثَرَةِ ‏ ‏وَأَنْ أَقْرَأَ وَأَنَا رَاكِعٌ ‏","","",""],[568,568,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏وَهْبُ بْنُ بَقِيَّةَ الْوَاسِطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ يُونُسَ يَعْنِي الْيَمَامِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ الْيَمَامِيِّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ زَيْدِ بْنِ حَسَنٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْبَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ يَا ‏ ‏عَلِيُّ ‏ ‏هَذَانِ سَيِّدَا ‏ ‏كُهُولِ ‏ ‏أَهْلِ الْجَنَّةِ وَشَبَابِهَا بَعْدَ النَّبِيِّينَ وَالْمُرْسَلِينَ ‏","","",""],[569,569,"","","‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏سَمِعَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏أَرَدْتُ أَنْ أَخْطُبَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَتَهُ فَقُلْتُ مَا لِي مِنْ شَيْءٍ فَكَيْفَ ثُمَّ ذَكَرْتُ صِلَتَهُ وَعَائِدَتَهُ فَخَطَبْتُهَا إِلَيْهِ فَقَالَ هَلْ لَكَ مِنْ شَيْءٍ قُلْتُ لَا قَالَ ‏ ‏فَأَيْنَ دِرْعُكَ ‏ ‏الْحُطَمِيَّةُ ‏ ‏الَّتِي أَعْطَيْتُكَ يَوْمَ كَذَا وَكَذَا قَالَ هِيَ عِنْدِي قَالَ فَأَعْطِهَا إِيَّاهُ ‏","","",""],[570,570,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسْتَخْدِمُهُ فَقَالَ أَلَا أَدُلُّكِ عَلَى مَا هُوَ خَيْرٌ لَكِ مِنْ ذَلِكَ ‏ ‏تُسَبِّحِينَ ثَلَاثًا وَثَلَاثِينَ وَتُكَبِّرِينَ ثَلَاثًا وَثَلَاثِينَ وَتَحْمَدِينَ ثَلَاثًا وَثَلَاثِينَ أَحَدُهَا أَرْبَعًا وَثَلَاثِينَ ‏","","",""],[571,571,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْأَعْلَى بْنُ حَمَّادٍ النَّرْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ مَسْلَمَةُ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سُفْيَانَ الثَّقَفِيِّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يُحِبُّ الْعَبْدَ الْمُؤْمِنَ الْمُفَتَّنَ التَّوَّابَ ‏","","",""],[572,572,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏فَكُنْتُ أَسْتَحِي أَنْ أَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَكَانِ ابْنَتِهِ فَأَمَرْتُ ‏ ‏الْمِقْدَادَ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏يَغْسِلُ ذَكَرَهُ وَيَتَوَضَّأُ ‏","","",""],[573,573,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ مُكَرَّمٍ الْكُوفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[574,574,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ بْنُ مِقْسَمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ الْعُكْلِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَانَ لِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَدْخَلَانِ بِاللَّيْلِ وَالنَّهَارِ وَكُنْتُ إِذَا دَخَلْتُ عَلَيْهِ وَهُوَ ‏ ‏يُصَلِّي تَنَحْنَحَ فَأَتَيْتُهُ ذَاتَ لَيْلَةٍ فَقَالَ أَتَدْرِي مَا أَحْدَثَ الْمَلَكُ اللَّيْلَةَ كُنْتُ أُصَلِّي فَسَمِعْتُ ‏ ‏خَشْفَةً ‏ ‏فِي الدَّارِ فَخَرَجْتُ فَإِذَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ مَا زِلْتُ هَذِهِ اللَّيْلَةَ أَنْتَظِرُكَ إِنَّ فِي بَيْتِكَ كَلْبًا فَلَمْ أَسْتَطِعْ الدُّخُولَ ‏ ‏وَإِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا جُنُبٌ وَلَا تِمْثَالٌ ‏","","",""],[575,575,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ النُّعْمَانِ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُضَحَّى ‏ ‏بِالْمُقَابَلَةِ ‏ ‏أَوْ ‏ ‏بِمُدَابَرَةٍ ‏ ‏أَوْ ‏ ‏شَرْقَاءَ ‏ ‏أَوْ ‏ ‏خَرْقَاءَ ‏ ‏أَوْ ‏ ‏جَدْعَاءَ ‏","","",""],[576,576,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالٍ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ الْأَجْدَعِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُصَلَّى بَعْدَ الْعَصْرِ إِلَّا أَنْ تَكُونَ الشَّمْسُ بَيْضَاءَ مُرْتَفِعَةً ‏","","",""],[577,577,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَقْرَأَ وَأَنَا رَاكِعٌ وَعَنْ خَاتَمِ الذَّهَبِ وَعَنْ ‏ ‏الْقَسِّيِّ ‏ ‏وَالْمُعَصْفَرِ ‏","","",""],[578,578,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو مُوسَى ‏ ‏إِلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏يَعُودُهُ ‏ ‏فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَعَائِدًا ‏ ‏جِئْتَ أَمْ شَامِتًا قَالَ لَا بَلْ عَائِدًا قَالَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنْ كُنْتَ جِئْتَ عَائِدًا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي ‏ ‏خِرَافَةِ ‏ ‏الْجَنَّةِ حَتَّى يَجْلِسَ فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ ‏","","",""],[579,579,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏فِي سَنَةِ سِتٍّ وَعِشْرِينَ وَمِائَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ خَالِدٍ الزَّنْجِيُّ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قُلْتُ ‏ ‏لِسُوَيْدٍ ‏ ‏وَلِمَ سُمِّيَ ‏ ‏الزَّنْجِيَّ ‏ ‏قَالَ كَانَ شَدِيدَ السَّوَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ ‏ ‏بِعَرَفَةَ ‏ ‏وَهُوَ مُرْدِفٌ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَقَالَ ‏ ‏هَذَا مَوْقِفٌ وَكُلُّ ‏ ‏عَرَفَةَ ‏ ‏مَوْقِفٌ ثُمَّ دَفَعَ فَجَعَلَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏وَالنَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا وَهُوَ يَلْتَفِتُ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ حَتَّى جَاءَ ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَجَمَعَ بَيْنَ الصَّلَاتَيْنِ ثُمَّ وَقَفَ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏فَأَرْدَفَ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏ثُمَّ وَقَفَ عَلَى ‏ ‏قُزَحَ ‏ ‏فَقَالَ هَذَا الْمَوْقِفُ وَكُلُّ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏مَوْقِفٌ ثُمَّ دَفَعَ فَجَعَلَ يَسِيرُ ‏ ‏الْعَنَقَ ‏ ‏وَالنَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا وَهُوَ يَلْتَفِتُ وَيَقُولُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏السَّكِينَةَ ‏ ‏أَيُّهَا النَّاسُ فَلَمَّا وَقَفَ عَلَى ‏ ‏مُحَسِّرٍ ‏ ‏قَرَعَ ‏ ‏رَاحِلَتَهُ ‏ ‏فَخَبَّتْ ‏ ‏بِهِ حَتَّى خَرَجَتْ مِنْ ‏ ‏الْوَادِي ‏ ‏ثُمَّ سَارَ مَسِيرَتَهُ حَتَّى أَتَى ‏ ‏الْجَمْرَةَ ‏ ‏ثُمَّ دَخَلَ ‏ ‏الْمَنْحَرَ ‏ ‏فَقَالَ هَذَا ‏ ‏الْمَنْحَرُ ‏ ‏وَكُلُّ ‏ ‏مِنًى ‏ ‏مَنْحَرٌ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏أَحْمَدَ بْنِ عَبْدَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏مِثْلَهُ أَوْ نَحْوَهُ ‏","","",""],[580,580,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ أَبُو مَعْمَرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ جَبِيرَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُبْغِضُ ‏ ‏الْعَرَبَ ‏ ‏إِلَّا مُنَافِقٌ ‏","","",""],[581,581,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ مَنْ زَعَمَ أَنَّ عِنْدَنَا شَيْئًا نَقْرَؤُهُ إِلَّا كِتَابَ اللَّهِ وَهَذِهِ الصَّحِيفَةَ صَحِيفَةٌ فِيهَا أَسْنَانُ الْإِبِلِ وَأَشْيَاءُ مِنْ الْجِرَاحَاتِ فَقَدْ كَذَبَ قَالَ وَفِيهَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةُ ‏ ‏حَرَمٌ مَا بَيْنَ ‏ ‏عَيْرٍ ‏ ‏إِلَى ‏ ‏ثَوْرٍ ‏ ‏فَمَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا حَدَثًا أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏ ‏وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ تَوَلَّى غَيْرَ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏ ‏وَذِمَّةُ ‏ ‏الْمُسْلِمِينَ وَاحِدَةٌ ‏ ‏يَسْعَى بِهَا ‏ ‏أَدْنَاهُمْ ‏","","",""],[582,582,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ غَفَلَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَلَأَنْ أَخِرَّ مِنْ السَّمَاءِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَكْذِبَ عَلَيْهِ وَإِذَا حَدَّثْتُكُمْ عَنْ غَيْرِهِ فَإِنَّمَا أَنَا رَجُلٌ مُحَارِبٌ وَالْحَرْبُ خَدْعَةٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ فِي آخِرِ الزَّمَانِ أَقْوَامٌ أَحْدَاثُ الْأَسْنَانِ سُفَهَاءُ الْأَحْلَامِ يَقُولُونَ مِنْ قَوْلِ خَيْرِ ‏ ‏الْبَرِيَّةِ ‏ ‏لَا يُجَاوِزُ إِيمَانُهُمْ حَنَاجِرَهُمْ فَأَيْنَمَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ فَإِنَّ قَتْلَهُمْ أَجْرٌ لِمَنْ قَتَلَهُمْ يَوْمَ الْقِيَامَةِ ‏","","",""],[583,583,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْأَحْزَابِ ‏ ‏شَغَلُونَا عَنْ ‏ ‏صَلَاةِ الْوُسْطَى ‏ ‏صَلَاةِ الْعَصْرِ ‏ ‏مَلَأَ اللَّهُ قُبُورَهُمْ وَبُيُوتَهُمْ نَارًا ثُمَّ صَلَّاهَا بَيْنَ الْعِشَاءَيْنِ ‏ ‏بَيْنِ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[584,584,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ أَبِي يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏فَاسْتَحْيَى أَنْ يَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَذْيِ ‏ ‏قَالَ فَقَالَ ‏ ‏لِلْمِقْدَادِ ‏ ‏سَلْ لِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَذْيِ ‏ ‏قَالَ فَسَأَلَهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ الْوُضُوءُ ‏","","",""],[585,585,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَقْرَأَ الرَّجُلُ وَهُوَ رَاكِعٌ أَوْ سَاجِدٌ ‏","","",""],[586,586,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ ‏ ‏تَنَوَّقُ ‏ ‏فِي ‏ ‏قُرَيْشٍ ‏ ‏وَتَدَعُنَا قَالَ وَعِنْدَكُمْ شَيْءٌ قَالَ قُلْتُ نَعَمْ ‏ ‏ابْنَةُ حَمْزَةَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَا تَحِلُّ لِي هِيَ ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ ‏","","",""],[587,587,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ جَالِسًا وَفِي يَدِهِ عُودٌ ‏ ‏يَنْكُتُ ‏ ‏بِهِ قَالَ فَرَفَعَ رَأْسَهُ فَقَالَ ‏ ‏مَا مِنْكُمْ مِنْ نَفْسٍ إِلَّا وَقَدْ عُلِمَ مَنْزِلُهَا مِنْ الْجَنَّةِ وَالنَّارِ قَالَ فَقَالُوا يَا رَسُولَ اللَّهِ فَلِمَ نَعْمَلُ قَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ‏ { ‏أَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ ‏ ‏لِلْعُسْرَى ‏ }","","",""],[588,588,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏وَاسْتَعْمَلَ عَلَيْهِمْ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ فَلَمَّا خَرَجُوا قَالَ ‏ ‏وَجَدَ ‏ ‏عَلَيْهِمْ فِي شَيْءٍ فَقَالَ قَالَ لَهُمْ أَلَيْسَ قَدْ أَمَرَكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُطِيعُونِي قَالَ قَالُوا بَلَى قَالَ فَقَالَ اجْمَعُوا حَطَبًا ثُمَّ دَعَا بِنَارٍ ‏ ‏فَأَضْرَمَهَا ‏ ‏فِيهِ ثُمَّ قَالَ ‏ ‏عَزَمْتُ ‏ ‏عَلَيْكُمْ لَتَدْخُلُنَّهَا قَالَ فَهَمَّ الْقَوْمُ أَنْ يَدْخُلُوهَا قَالَ فَقَالَ لَهُمْ شَابٌّ مِنْهُمْ إِنَّمَا فَرَرْتُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ النَّارِ فَلَا تَعْجَلُوا حَتَّى تَلْقَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنْ أَمَرَكُمْ أَنْ تَدْخُلُوهَا فَادْخُلُوا قَالَ فَرَجَعُوا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرُوهُ فَقَالَ لَهُمْ ‏ ‏لَوْ دَخَلْتُمُوهَا مَا خَرَجْتُمْ مِنْهَا أَبَدًا إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ ‏","","",""],[589,589,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ جَنَازَةً فِي ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَقُمْتُ فَقَالَ لِي ‏ ‏نَافِعُ بْنُ جُبَيْرٍ ‏ ‏اجْلِسْ فَإِنِّي سَأُخْبِرُكَ فِي هَذَا بِثَبْتٍ ‏ ‏حَدَّثَنِي ‏ ‏مَسْعُودُ بْنُ الْحَكَمِ الزُّرَقِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِرَحَبَةِ ‏ ‏الْكُوفَةِ ‏ ‏وَهُوَ يَقُولُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنَا بِالْقِيَامِ فِي الْجِنَازَةِ ثُمَّ جَلَسَ بَعْدَ ذَلِكَ وَأَمَرَنَا بِالْجُلُوسِ ‏","","",""],[590,590,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الدَّانَاجِ ‏ ‏عَنْ ‏ ‏حُضَيْنٍ أَبِي سَاسَانَ الرَّقَاشِيِّ ‏ ‏أَنَّهُ ‏ ‏قَدِمَ نَاسٌ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏عَلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَخْبَرُوهُ بِمَا كَانَ مِنْ أَمْرِ ‏ ‏الْوَلِيدِ ‏ ‏أَيْ بِشُرْبِهِ الْخَمْرَ ‏ ‏فَكَلَّمَهُ ‏ ‏عَلِيٌّ ‏ ‏فِي ذَلِكَ فَقَالَ دُونَكَ ابْنَ عَمِّكَ فَأَقِمْ عَلَيْهِ الْحَدَّ فَقَالَ يَا ‏ ‏حَسَنُ ‏ ‏قُمْ فَاجْلِدْهُ قَالَ مَا أَنْتَ مِنْ هَذَا فِي شَيْءٍ وَلِّ هَذَا غَيْرَكَ قَالَ بَلْ ضَعُفْتَ وَوَهَنْتَ وَعَجَزْتَ قُمْ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏فَجَعَلَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَضْرِبُهُ وَيَعُدُّ ‏ ‏عَلِيٌّ ‏ ‏حَتَّى بَلَغَ أَرْبَعِينَ ثُمَّ قَالَ أَمْسِكْ ‏ ‏أَوْ قَالَ كُفَّ ‏ ‏جَلَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعِينَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏أَرْبَعِينَ وَكَمَّلَهَا ‏ ‏عُمَرُ ‏ ‏ثَمَانِينَ وَكُلٌّ سُنَّةٌ ‏","","",""],[591,591,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ بْنِ يَزِيدَ بْنِ رُكَانَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ الْخَوْلَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ ‏ ‏عَلِيٌّ ‏ ‏بَيْتِي فَدَعَا بِوَضُوءٍ ‏ ‏فَجِئْتُهُ ‏ ‏بِقَعْبٍ ‏ ‏يَأْخُذُ الْمُدَّ أَوْ قَرِيبَهُ حَتَّى وُضِعَ بَيْنَ يَدَيْهِ وَقَدْ بَالَ فَقَالَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَلَا أَتَوَضَّأُ لَكَ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى فِدَاكَ أَبِي وَأُمِّي قَالَ ‏ ‏فَوُضِعَ لَهُ إِنَاءٌ فَغَسَلَ يَدَيْهِ ثُمَّ مَضْمَضَ ‏ ‏وَاسْتَنْشَقَ وَاسْتَنْثَرَ ثُمَّ أَخَذَ بِيَدَيْهِ فَصَكَّ بِهِمَا وَجْهَهُ وَأَلْقَمَ إِبْهَامَهُ مَا أَقْبَلَ مِنْ أُذُنَيْهِ قَالَ ثُمَّ عَادَ فِي مِثْلِ ذَلِكَ ثَلَاثًا ثُمَّ أَخَذَ كَفًّا مِنْ مَاءٍ بِيَدِهِ الْيُمْنَى فَأَفْرَغَهَا عَلَى نَاصِيَتِهِ ثُمَّ أَرْسَلَهَا تَسِيلُ عَلَى وَجْهِهِ ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى الْمِرْفَقِ ثَلَاثًا ثُمَّ يَدَهُ الْأُخْرَى مِثْلَ ذَلِكَ ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ مِنْ ظُهُورِهِمَا ثُمَّ أَخَذَ بِكَفَّيْهِ مِنْ الْمَاءِ فَصَكَّ بِهِمَا عَلَى قَدَمَيْهِ وَفِيهِمَا النَّعْلُ ثُمَّ قَلَبَهَا بِهَا ثُمَّ عَلَى الرِّجْلِ الْأُخْرَى مِثْلَ ذَلِكَ قَالَ فَقُلْتُ وَفِي النَّعْلَيْنِ قَالَ وَفِي النَّعْلَيْنِ قُلْتُ وَفِي النَّعْلَيْنِ قَالَ وَفِي النَّعْلَيْنِ قُلْتُ وَفِي النَّعْلَيْنِ قَالَ وَفِي النَّعْلَيْنِ ‏","","",""],[592,592,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏ذُكِرَ ‏ ‏الْخَوَارِجُ ‏ ‏فَقَالَ فِيهِمْ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ أَوْ مُودَنُ الْيَدِ أَوْ ‏ ‏مُثَدَّنُ الْيَدِ لَوْلَا أَنْ ‏ ‏تَبْطَرُوا ‏ ‏لَحَدَّثْتُكُمْ بِمَا وَعَدَ اللَّهُ الَّذِينَ يَقْتُلُونَهُمْ عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏قُلْتُ أَنْتَ سَمِعْتَهُ مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏","","",""],[593,593,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقْرِئُنَا الْقُرْآنَ مَا لَمْ يَكُنْ جُنُبًا ‏","","",""],[594,594,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُمَرَ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِذَا بَعَثْتَنِي أَكُونُ ‏ ‏كَالسِّكَّةِ ‏ ‏الْمُحْمَاةِ أَمْ الشَّاهِدُ يَرَى مَا لَا يَرَى الْغَائِبُ قَالَ ‏ ‏الشَّاهِدُ يَرَى مَا لَا يَرَى الْغَائِبُ ‏","","",""],[595,595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رِبْعِيًّا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْذِبُوا عَلَيَّ فَإِنَّهُ مَنْ يَكْذِبْ عَلَيَّ ‏ ‏يَلِجْ ‏ ‏النَّارَ ‏","","",""],[596,596,"","","‏ ‏حَدَّثَنَاه ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْذِبُوا عَلَيَّ فَإِنَّهُ مَنْ يَكْذِبْ عَلَيَّ ‏ ‏يَلِجْ ‏ ‏النَّارَ ‏","","",""],[597,597,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏مَسْعُودِ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَدْ ‏ ‏رَأَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَقُمْنَا وَقَعَدَ فَقَعَدْنَا ‏","","",""],[598,598,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏أَبِى زُرْعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ نُجَيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ جُنُبٌ وَلَا صُورَةٌ وَلَا كَلْبٌ ‏","","",""],[599,599,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏جُرَيِّ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُضَحَّى ‏ ‏بِعَضْبَاءِ ‏ ‏الْقَرْنِ وَالْأُذُنِ ‏","","",""],[600,600,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْت ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏لَيْسَ ‏ ‏بِالْكُوفَةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدِيثٌ أَصَحُّ مِنْ هَذَا ‏","","",""]];
